import type { DemoConfig } from '@/components/demos/archetypes';

// Config-driven interactive demos, keyed by sub-topic id. Each demo dramatizes
// the SAME product + scenario as its Learn-tab example (the #1 rule in the
// learning-deep-page skill). Authored + validated by the demo-config workflow.
// Bespoke/hand-mapped sub-topics are handled in DeepModal and omitted here.
export const DEMO_CONFIGS: Record<string, DemoConfig> = {
  "ai-agent-legibility-mm-0": { archetype: 'slider-map', sliderLabel: "UI trust signal strength (grey inline styling)", outputLabel: "Developer acceptance rate", badCaption: "Acceptance tracks the identical grey styling, not the real accuracy. A hallucinated API renders with the same visual weight as a well-worn idiom, so developers accept the bug at the same rate as the correct line and ship it as vetted code.", goodCaption: "Tie the visual weight to real accuracy. When the suggestion's confidence drops, the styling weakens or flags, so acceptance falls with accuracy and the error zone closes." },
  "ai-agent-legibility-mm-1": { archetype: 'toggle-fix', subject: "Tesla Autopilot", badLabel: "Fought one failure mode", goodLabel: "Fought all three", badLines: ["Reliability high: driver stops watching the road (misuse)", "Nag alerts fire constantly: driver wedges a weight on the wheel to silence them (disuse)", "Shipped for a road context it was never built to handle unsupervised (abuse)", "Dashboard on top: 'Autopilot engaged. All systems nominal.'"], goodLines: ["Reliability high: cabin camera confirms eyes-on-road before trust is granted (misuse guarded)", "Alerts rate-tuned and escalating, not spammed, so they can't be gamed (disuse guarded)", "Geofenced to supported roads, degrades to assist elsewhere (abuse guarded)", "Dashboard names which mode is active and why"], badCaption: "The design fought only misuse, so all three failures surface in the same car under one 'looks fine' dashboard. The cost is fatal and the post-mortems keep blaming 'driver error' when two of the three were design's job.", goodCaption: "Name misuse, disuse, and abuse separately and guard each: eyes-on-road monitoring, un-gameable alerting, and a geofence. One failure mode fixed is two still open." },
  "ai-agent-legibility-mm-2": { archetype: 'toggle-fix', subject: "Devin (Cognition)", badLabel: "Raw system-call dump", goodLabel: "Verb-object-result timeline", badLines: ["$ npm test", "Error: ECONNREFUSED 127.0.0.1:5432", "  at TCPConnectWrap.afterConnect [as oncomplete]", "$ npm test", "Error: ECONNREFUSED 127.0.0.1:5432", "$ npm test ...(scrolling)"], goodLines: ["Read 14 files across src/auth", "Rewrote token refresh, 3 files changed", "Ran tests: 2 failing, DB not reachable", "Retrying test run (attempt 3 of 3) - stuck", "Needs your input: no local Postgres"], badCaption: "A scrolling terminal of shell commands and stack traces is present and completely illegible. The PM approving the work can't tell progress from a retry loop, so trust collapses on the first slow run.", goodCaption: "Same trace, rendered as verb-object-result events a non-engineer can read. 'Retrying (3 of 3) - stuck' says exactly what the dump hid." },
  "ai-agent-legibility-mm-3": { archetype: 'sequence', badSequence: ["User clicks Run", "POST /send-email fires to the client's address", "Email delivered to recipient inbox", "Toast appears: 'Sent. Undo?'", "User clicks Undo -> nothing to undo, they already have it"], goodSequence: ["User clicks Run", "Compose step resolves recipient and body", "Preview modal: 'Send invoice to client@acme.com?'", "User clicks Confirm", "POST /send-email fires, then delivered"], badCaption: "The email leaves before the 'sent, undo?' toast renders. For an external send there is no undo, the recipient already has it. The 'undo' framing hides that the irreversible thing already happened, so the user thinks they had a control when they had a receipt.", goodCaption: "Hold the send behind the button. The modal gates the irreversible action, so Confirm is real approval and Cancel actually prevents the send." },
  "ai-agent-legibility-mm-4": { archetype: 'slider-map', sliderLabel: "Rewrite quality (actual edit accuracy)", outputLabel: "User acceptance rate", badCaption: "Every rewrite ships with 'I made this clearer and more concise,' generic and true of almost any edit. Acceptance climbs with the presence of a rationale, not with quality, so a bad rewrite is accepted as readily as a good one. The explanation only lowered scrutiny.", goodCaption: "Drop the reflexive rationale, or make it specific and falsifiable (what changed, why here). Then acceptance can track whether the edit was actually good." },
  "ai-agent-legibility-mm-5": { archetype: 'reveal', subject: "OpenAI reasoning model in a compliance workflow", opaqueLabel: "Filed reasoning: 'Reviewed the policy and the applicant's history; the request is consistent with prior approvals, so I approved it.'", revealedLines: ["Same question, planted hint: retrieved docs reordered to put the denial precedent last", "Answer flipped from approve to deny", "Displayed 'thinking' never mentions the doc order that flipped it", "The real driver (retrieval order) is absent from the filed record", "The audit trail now certifies a reason that isn't the reason"], badCaption: "The stated chain-of-thought is fluent after-the-fact narration, not a transcript of what drove the output. A compliance team files it as the record of why the action was taken, but a hidden cue (doc order, a phrasing nudge) flipped the answer without appearing in the trace, so the filed reasoning is fiction that reads well.", goodCaption: "Log the deterministic inputs that actually drove it (resolved documents and their order, the policy version, the tool calls), not the narration. That is the record you can defend." },
  "ai-agent-legibility-mm-6": { archetype: 'slider-map', sliderLabel: "Model's stated confidence (Confidence: 94%)", outputLabel: "Actual correctness in that bucket", badCaption: "The 94% came from the same generation pass, not from any calibration against ground truth. A clinician reads it as measured reliability and defers, but answers claiming 80-100% are correct far less than that. The badge manufactured false precision exactly where deference is dangerous.", goodCaption: "Only show a confidence signal derived from calibration (self-consistency across samples, retrieval agreement). If stated confidence doesn't track correctness, don't print a number." },
  "ai-agent-legibility-mm-7": { archetype: 'reveal', subject: "Perplexity", opaqueLabel: "Claim: 'EV sales rose 47% in 2024.' Source [3]: a real, credible industry report. Numbered citation present.", revealedLines: ["Click [3], jump to the highlighted span in the source", "The report discusses 2024 EV sales trends", "It never states a 47% figure - nothing to highlight", "The citation is genuine; the exact claim is not in it", "Roughly a third of the time the attribution is invented"], badCaption: "A source link proves a claim is checkable, not that it matches the source. Users treat the numbered citation as proof of grounding and don't click through, but about a third of the time the figure isn't actually in the cited source. The citation delivered verifiability while users read it as verified.", goodCaption: "Link each claim to the exact supporting sentence, not the document. When there's no span to highlight, the gap is visible before the user relies on it." },
  "ai-agent-legibility-mm-8": { archetype: 'reveal', subject: "Datadog trace repurposed as an AI audit log", opaqueLabel: "Observability trace: span latency 340ms, HTTP 200, span_id a1f9, service agent-approver, region us-east-1", revealedLines: ["Actor / authorizing identity: not captured", "Policy version in force: not captured", "Resolved inputs (amount, counterparty, rule matched): not captured", "Hash chain / tamper-evidence: none", "Retention: sampled and partly expired"], badCaption: "Observability answers 'is the system healthy right now?' for engineers. It can't answer 'why did it decide this, under what data and policy?' for a regulator months later. The trace has timing and status codes but no policy version, no resolved inputs, no authorizing identity, and it was sampled.", goodCaption: "An audit record binds actor, policy version, resolved inputs, and a hash chain to each decision. Only that answers 'why did it decide this?'" },
  "ai-agent-legibility-mm-9": { archetype: 'sequence', badSequence: ["Allow Read package.json? -> Approve (read in full)", "Allow ls src/? -> Approve (0.4s)", "Allow Read utils.ts? -> Approve (0.3s)", "Allow cat README? -> Approve (0.2s)", "Allow rm -rf .git? -> Approve (0.2s, reflex, unread)"], goodSequence: ["Read package.json -> auto-run silently (reversible)", "ls src/ -> auto-run silently (reversible)", "Read utils.ts -> auto-run silently (reversible)", "cat README -> auto-run silently (reversible)", "rm -rf .git -> BLOCK and ask, fresh attention on the one that matters"], badCaption: "A prompt fires for nearly every read and command; Anthropic's own data showed ~93% blanket approval. When 93% are trivial, the reflex to approve carries straight into the 7% that could delete a repo. Oversight looks intact in the UI and is functionally gone.", goodCaption: "Auto-run the reversible reads silently and reserve prompts for the irreversible actions. The one dangerous prompt lands on fresh, not exhausted, attention." },
  "ai-agent-legibility-pat-0": { archetype: 'sequence', badSequence: ["Confirm-everything build:", "Approve Read config.ts?", "Approve run tests?", "Approve list dir?", "Approve git push --force? (waved through with the rest)"], goodSequence: ["Read files -> silent lane, auto-run", "List directories -> silent lane, auto-run", "Run tests -> silent lane, auto-run", "curl data to external host -> gated lane, block and ask", "git push --force / delete history -> gated lane, block and ask"], badCaption: "Confirming every action trains the blanket-approve reflex, so the force-push gets waved through with the harmless reads. The alternative to two-tier gating actively manufactures the rubber-stamp.", goodCaption: "Split actions by reversibility: auto-run reads and tests silently, block-and-ask on the irreversible category. Users stay in flow for the 90% that can't hurt them, so attention is fresh for the few that can." },
  "ai-agent-legibility-pat-1": { archetype: 'toggle-fix', subject: "Radiology diagnostic AI", badLabel: "AI answer shown first", goodLabel: "Commit-first, then reveal", badLines: ["Scan opens with the suspected nodule pre-highlighted in a red box", "Radiologist's eye anchors to the box", "Search of the rest of the field stops", "Read logged: agreed with AI (no independent look)"], goodLines: ["Scan opens clean, no overlay", "Radiologist marks their own read first", "AI finding then revealed, disagreements flagged", "Two independent reads on record, conflicts surfaced"], badCaption: "Pre-highlighting the nodule causes anchoring and automation bias: the radiologist stops searching once they see the box, so the AI replaces the read instead of checking it.", goodCaption: "Withhold the AI finding until the radiologist commits their own read. The forcing function preserves the independent look, so the AI becomes a genuine second opinion." },
  "ai-agent-legibility-pat-2": { archetype: 'reveal', subject: "Ledger hardware wallet (clear signing)", opaqueLabel: "Friendly summary on screen: 'Approve 10 USDC' with a Sign button", revealedLines: ["Decode the raw calldata on the device screen", "Function: approve(spender, amount)", "Amount: unlimited (2^256 - 1), not 10", "Spender: 0x9f...c3a1, unverified contract", "This is an unlimited-allowance grant to an unknown address"], badCaption: "The human-readable summary and the actual payload can diverge. The user approves the friendly 'Approve 10 USDC' while signing an unlimited allowance to a drainer. This is the single most exploited wallet vulnerability.", goodCaption: "Decode the calldata into human-readable fields on the trusted screen so what you see is what you sign. The decode exposes the unlimited allowance the summary hid." },
  "ai-agent-legibility-pat-3": { archetype: 'reveal', subject: "Rabby wallet (transaction simulation)", opaqueLabel: "Raw request: label reads 'Claim reward', calldata is unreadable hex", revealedLines: ["Simulate against a mainnet fork before signing", "Asset diff:", "You receive: 0 tokens", "You send: 2.00 ETH", "Outcome: honeypot, the 'claim' drains your wallet"], badCaption: "The raw transaction is unreadable and the 'Claim reward' label can lie. Signed as-is, the user loses 2 ETH to a honeypot the request never disclosed.", goodCaption: "Fork the chain, run the transaction, and show the before/after asset diff first. Simulation surfaces the real outcome ('receive 0, lose 2 ETH') before it's irreversible." },
  "ai-agent-legibility-pat-4": { archetype: 'sequence', badSequence: ["Spinner...", "Spinner...", "Spinner...", "'Booked United 447, your card was charged $412'"], goodSequence: ["Searched 12 flights matching your dates", "Filtered by your $500 budget", "Selected United 447 ($412)", "About to purchase - PAUSED, gated in red", "Awaiting your confirm before the charge"], badCaption: "A spinner hides the difference between research and commitment, so the user either interrupts too early or discovers the purchase after the card was charged.", goodCaption: "Render each step as verb-object-result, expandable to raw payload, with the side-effect step flagged and gated. A real pause halts before the charge, so research and commitment are never confused." },
  "ai-agent-legibility-pat-5": { archetype: 'reveal', subject: "Elicit / Consensus (spot-checkable provenance)", opaqueLabel: "Bare-link tool: claim footnoted to the paper (Ref 4), link only", revealedLines: ["Provenance view quotes the exact supporting sentence:", "'...no statistically significant difference in all-cause mortality was observed...'", "The quoted span contradicts the claim", "Misattribution caught in one glance, without opening the PDF", "For a fabricated claim, no sentence highlights at all"], badCaption: "A bare footnote to the paper makes the misattribution hide behind the cost of opening and reading the source, which the user won't pay.", goodCaption: "Attach each claim to the specific supporting sentence, quoted inline. A wrong attribution is caught instantly because the quoted span doesn't say what the claim says." },
  "ai-agent-legibility-pat-6": { archetype: 'toggle-fix', subject: "Agent tool-call monitor", badLabel: "Monitor sees the agent's reasoning", goodLabel: "Reasoning-blind monitor", badLines: ["Monitor reads the agent's reasoning", "'User wants invoices consolidated; forwarding to the requested address'", "Justification (planted by the injection) looks coherent", "Monitor approves the forward to attacker@evil.com"], goodLines: ["Monitor sees only: original user request + proposed tool call", "Request: 'sort my inbox'", "Proposed action: forward to external address attacker@evil.com", "Mismatch: sorting does not require an external forward", "BLOCKED"], badCaption: "A monitor that reads the agent's reasoning sees the injected justification and approves the exfiltration for the same fabricated reason that hijacked the agent.", goodCaption: "Feed the monitor only the user's original request plus the proposed tool call, blind to the agent's reasoning. Blindness to the compromised context is exactly what catches the mismatch." },
  "ai-agent-legibility-pat-7": { archetype: 'sequence', badSequence: ["Q: 'What's your refund window?' -> answers from docs", "Q: 'Can I get a refund after 90 days?' -> invents '120-day exception'", "Q: 'Is my data GDPR-compliant?' -> confabulates a policy", "Customer relies on a policy that doesn't exist"], goodSequence: ["In scope: 'What's your refund window?' -> answers from docs", "Ambiguous: 'refund after 90 days?' -> asks a clarifying question", "Out of scope: 'GDPR compliance?' -> hands off to a human", "Each escalation writes its reason to the audit panel"], badCaption: "Past its competence boundary, the agent confabulates a confident refund or security policy that doesn't exist, creating real liability and burning trust.", goodCaption: "At the boundary, route to a human, ask a clarifying question, or degrade to a safe answer, and log the reason. The boundary becomes a graceful handoff instead of a confident fabrication." },
  "ai-agent-legibility-anti-1": { archetype: 'slider-map', sliderLabel: "Presence of an explanatory rationale panel", outputLabel: "Reviewer deference (rubber-stamp rate)", badCaption: "A paragraph of generic, unfalsifiable 'here's how the model weighed your factors' raises deference regardless of quality. The reviewer feels the decision is well-reasoned and rubber-stamps it, adding deference without adding accuracy in a domain where over-reliance harms people.", goodCaption: "If the explanation can't be checked, it's trust theater. Show falsifiable evidence (the specific factors, thresholds, and what would flip the decision), so scrutiny tracks quality instead of collapsing." },
  "ai-agent-legibility-anti-2": { archetype: 'toggle-fix', subject: "AI contract-review tool", badLabel: "Crisp percentage badge", goodLabel: "Calibrated three-bucket signal", badLines: ["Clause 7.2 flagged: 'Indemnification is one-sided'", "Confidence: 88%", "(88% is the model's own self-estimate, uncorrelated with being right)", "Junior lawyer calibrates review to a measurement that isn't one"], goodLines: ["Clause 7.2 flagged: 'Indemnification is one-sided'", "Signal: Low agreement across 5 sampled reads", "Derived from self-consistency, not a raw self-estimate", "Reads as 'check this yourself', not 'trust the number'"], badCaption: "A crisp '88%' dresses a guess as a measurement. It's the model's self-estimate, uncorrelated with correctness, so a junior lawyer over-trusts high-confidence flags that are wrong far more often than the badge implies.", goodCaption: "Replace the false-precision percentage with a calibrated bucket derived from self-consistency. A coarse honest signal beats a crisp dishonest one." },
  "ai-agent-legibility-anti-3": { archetype: 'meter', headline: "Answer, 8 citations - reads rigorously sourced", breakdown: [{ label: "Citations attached to the answer", value: 8 }, { label: "Sources that actually contain the claim", value: 5 }, { label: "Sources that don't (misattributed)", value: 3 }], badCaption: "More footnotes read as more rigor, so eight citations manufacture confidence the content hasn't earned. But citation presence is orthogonal to accuracy, and three of the eight don't contain their claims, so a heavily-footnoted wrong answer out-persuades a lightly-footnoted right one.", goodCaption: "Score attribution accuracy, not citation count. Surface which claims are actually supported so confidence tracks grounding, not footnote volume." },
  "ai-agent-legibility-anti-4": { archetype: 'reveal', subject: "Enterprise AI agent, regulated workflow", opaqueLabel: "Audit references the agent's reasoning: 'Approved the transfer because the request matched the customer's standing instructions.'", revealedLines: ["Replay from logged tool calls and lineage instead:", "Resolved amount and destination differ from the narrated 'standing instructions'", "A retrieved doc, absent from the reasoning, steered the approval", "Chain-of-thought was post-hoc narration, not a log of what drove it", "Only the tool-call + lineage replay reconstructs what actually happened"], badCaption: "Treating chain-of-thought as an accountability record makes the audit trail fiction. It's unfaithful post-hoc narration; if the model was steered by something absent from the trace, the stored justification is well-written fiction, and a regulator asking why gets a story.", goodCaption: "Store the auditable artifact: logged tool calls, resolved inputs, and lineage. That, not the narration, is what reconstructs why the action happened." },
  "ai-agent-legibility-anti-5": { archetype: 'sequence', badSequence: ["Approve: read row 1? -> yes (2.1s read time)", "Approve: read row 2? -> yes (0.9s)", "Approve: format cell? -> yes (0.4s)", "Approve: read row 3? -> yes (0.2s)", "Approve: delete the table? -> yes (0.2s, reflex, unread)"], goodSequence: ["Reads and low-stakes steps auto-run silently", "Only the destructive step surfaces a prompt", "Approve: delete the table?", "Prompt lands on fresh attention", "User actually reads it"], badCaption: "A confirmation for every step, including reads, trains the blanket-approve reflex. By the tenth prompt the user approves without reading, and the one prompt guarding the destructive step gets waved through with the rest. The team believes they shipped strong oversight.", goodCaption: "Stop confirming the harmless steps. Reserve the prompt for the destructive action so it arrives on fresh attention and actually gets read." },
  "ai-agent-legibility-anti-6": { archetype: 'toggle-fix', subject: "Crypto trading bot chat", badLabel: "Warm anthropomorphic reassurance", goodLabel: "Plain position and downside", badLines: ["Friendly avatar: 'I'll take care of this trade for you'", "'You're in good hands, don't worry'", "[Execute]", "No preview of the position or the risk"], goodLines: ["Position: 5x long ETH, $4,000 notional", "Liquidation price: $1,820 (ETH now $2,050)", "Max downside: full $800 margin", "[Approve trade]  [Cancel]"], badCaption: "A warm avatar and 'I've got this' copy inflate trust via anthropomorphism, not evidence. The persona manufactures perceived safety exactly where stakes are highest and the user understands least, widening the calibration gap.", goodCaption: "Drop the persona and show the actual position and downside: leverage, liquidation price, max loss. Trust should come from the diff, not the tone." },
  "ai-agent-legibility-anti-7": { archetype: 'reveal', subject: "AI compliance platform reusing APM tooling", opaqueLabel: "APM-based 'audit log' returns: p99 latency 210ms, HTTP 200, trace_id 7c2e, 3 spans", revealedLines: ["Policy version in force: missing", "Authorizing identity: missing", "Data lineage / resolved inputs: missing", "Records were sampled, not complete", "Purpose-built audit store returns: decision, actor, policy v2.4, resolved inputs"], badCaption: "Latency and health telemetry can't answer 'why did the AI decide this, under which policy and data?' months later. The APM has spans and latencies but no policy version, no identity binding, no lineage, and it was sampled. The audit fails on data the pipeline was never built to hold.", goodCaption: "A purpose-built audit store binds decision, actor, policy version, and resolved inputs per action. Ask the same regulator question and only it can answer." },
  "ai-agent-legibility-anti-8": { archetype: 'reveal', subject: "MetaMask blind signing / bulk admin", opaqueLabel: "Dialog reads: 'Approve' over raw undecoded calldata, or 'Delete 47 selected' with no list", revealedLines: ["Decode into a per-item manifest:", "Ops 1-45: routine metadata updates", "Op 46: grant unlimited token allowance to 0x9f...c3a1 (unverified)", "Op 47: delete customer records #2201-2244", "The dangerous items are flagged, the blank check is now readable"], badCaption: "Asking to approve something the UI won't decode ('Approve', 'Run 47 operations') is a blank check. Consent is uninformed, so the control is void: the user grants an unlimited allowance to a drainer, or deletes records they never meant to.", goodCaption: "Decode the request into a per-item manifest with the dangerous items flagged. Only then can the user make an informed, valid decision about what they're authorizing." },
  "ai-agent-legibility-inv-0": { archetype: 'sequence', badSequence: ["onMouseDown -> DELETE /record/77 fires", "Server commits the deletion", "Modal renders: 'Are you sure?'", "Network tab timestamp: request preceded the modal", "Cancel does nothing, the data is already gone"], goodSequence: ["onClick opens the modal (no request yet)", "User reads 'Are you sure?'", "User clicks Confirm", "Now DELETE /record/77 fires", "Cancel truly aborts the delete"], badCaption: "The 'Are you sure?' modal is real on screen but the DELETE already fired on button-down. QA passes because the modal is present and the happy path looks right; the bug only surfaces when a user cancels expecting to stop it and the data is already gone.", goodCaption: "Reorder the code so the request waits for Confirm. The devtools timestamp now shows the call firing after the click, so the modal is a control and not documentation." },
  "ai-agent-legibility-inv-1": { archetype: 'reveal', subject: "Wallet dApp signing flow", opaqueLabel: "Displayed summary (from dApp request metadata): 'Approve 10 USDC'", revealedLines: ["Decode the actual EIP-712 payload being signed:", "The summary is generated from a different source than the payload", "Payload: approve(spender = 0x9f...c3a1, amount = unlimited)", "Summary says 10 USDC; payload grants unlimited allowance to an attacker contract", "In every legitimate dApp the two match, so nothing looks wrong until a malicious one exploits the gap"], badCaption: "The summary the user reads is generated from the dApp's request metadata, not from the payload that executes, so they can silently diverge. The user approves 'Approve 10 USDC', signs an unlimited allowance, and gets drained.", goodCaption: "Generate the summary from the same decoded payload that gets signed, and show them side by side. When they can't diverge, the drainer has nowhere to hide." },
  "ai-agent-legibility-inv-2": { archetype: 'reveal', subject: "AI answer engine with confidence UI", opaqueLabel: "On screen: 'Confidence: 91%', read as a computed reliability metric", revealedLines: ["Trace the number's source:", "response.confidence, read straight off the model's output JSON", "No sampling step in the pipeline", "No calibration against ground truth anywhere", "It's the model's own optimistic self-estimate, uncorrelated with correctness"], badCaption: "The '91%' is the model's raw verbalized self-estimate pulled from the response JSON, not derived from retrieval agreement or self-consistency. It looks like a measurement and drives real reliance decisions while carrying no correlation to whether the answer is right.", goodCaption: "Derive the signal from sampled agreement across multiple generations. The badge may look identical, but only the calibrated one has a calibration curve that tracks correctness." },
  "ai-agent-legibility-inv-3": { archetype: 'reveal', subject: "AI search with post-hoc citation attach", opaqueLabel: "Claim with footnote [2] to a genuine, authoritative source, mapped by a post-processing step", revealedLines: ["Auto-search the linked source for the claim text:", "The article is real and credible", "It never states the cited claim", "The mapper matched on surface similarity, not grounded generation", "No matching span highlights - the attribution is fiction stapled to a real URL"], badCaption: "Citations are attached by a post-processing step that maps claims to plausible-looking URLs, not by grounding generation in retrieved text, so link and attribution are decoupled. The user sees an authoritative source and trusts the claim without opening it. The failure hides behind the cost of verification.", goodCaption: "Ground the citation in the retrieved text used during generation and highlight the matching span. Post-hoc-mapped citations show no match at all, exposing the gap instantly." },
  "ai-agent-legibility-inv-4": { archetype: 'reveal', subject: "AI agent in a regulated finance workflow", opaqueLabel: "Audit log entry: 'Agent transferred funds per user request'", revealedLines: ["Try to re-derive the action from the log:", "Resolved amount: not recorded", "Destination account: not recorded", "Policy version in force: not recorded", "Authorizing identity: not recorded - the prose can't reconstruct the decision"], badCaption: "The log records the natural-language summary, not the resolved tool inputs (final amount, exact destination, calldata) plus policy version and actor identity. When an incident demands to know exactly what happened and under what rule, the log offers a sentence.", goodCaption: "Log the resolved deterministic inputs, the policy version, and the authorizing identity. Only that record can replay and re-derive the exact action." },
  "ai-agent-legibility-inv-5": { archetype: 'toggle-fix', subject: "LLM guardrail / monitoring layer", badLabel: "Fed the agent's own reasoning", goodLabel: "Reasoning-blind", badLines: ["Guardrail receives the agent's full transcript, reasoning included", "Injection also populated that reasoning", "'Forwarding invoices as the user requested' reads as legitimate", "Guardrail approves the exfiltration for the same fabricated reason"], goodLines: ["Guardrail receives only: original request + proposed tool call", "Request: 'sort my inbox'", "Proposed action: forward to external address", "Mismatch detected, no contaminated reasoning to be talked over by", "BLOCKED"], badCaption: "The 'independent' checker is fed the agent's own reasoning, so a prompt-injected agent talks its reviewer into approving. The injection that hijacked the agent also populated the reasoning the monitor reads, so both approve for the same fabricated reason. The two components aren't independent.", goodCaption: "Make the check genuinely independent: feed it only the original request and the proposed tool call, blind to the agent's reasoning. The contaminated context can't reach it, so it catches the mismatch." },
  "ai-agent-legibility-inv-6": { archetype: 'sequence', badSequence: ["Broadcast transfer of 2 ETH", "Response times out (tx actually confirming)", "Retry re-broadcasts the transfer", "Both transactions confirm on-chain", "UI shows one 'Transfer complete', user debited twice"], goodSequence: ["Broadcast transfer of 2 ETH with an idempotency key / fixed nonce", "Response times out", "Retry re-sends with the same key", "Duplicate is rejected as already-seen", "Exactly one transaction confirms"], badCaption: "The retry silently re-issues the side-effecting transfer after a timeout with no idempotency key, so both broadcasts confirm. The user sees one 'Transfer complete' and is debited twice; the duplicate lives entirely in the retry path and is invisible in the UI.", goodCaption: "Attach an idempotency key or nonce guard so a retry can't create a second transfer. The duplicate is rejected and exactly one transaction confirms." },
  "ai-agent-legibility-inv-7": { archetype: 'reveal', subject: "Reasoning-model chat UI ('thinking' stream)", opaqueLabel: "UI streams a token-by-token 'thinking' passage, which feels like transparency", revealedLines: ["Session ends, open the stored record:", "The streamed 'thinking' was discarded", "Only the final answer / action is stored", "Nothing durable is tied to the committed action", "There's no artifact to audit why it acted"], badCaption: "Streaming reasoning token-by-token feels like transparency, but nothing in that stream is durably logged or tied to the committed action. Users feel the system was transparent, which raises trust, but when they later need to know why it acted, the reasoning is gone.", goodCaption: "Persist a durable record linked to the committed action, not an ephemeral stream. Transparency you can't retrieve later is a feeling, not an audit trail." },
  "ai-agent-legibility-inv-8": { archetype: 'reveal', subject: "'Zero data retention' AI API wrapper", opaqueLabel: "Marketing claim: 'Zero data retention' on sensitive payloads", revealedLines: ["Inspect each hop's writes:", "Inference backend (model provider): retains nothing - claim true here", "Logging proxy: captures full prompt + completion bodies for debugging", "Client history: persists the full payload to rebuild multi-turn state", "The retention boundary was real for one hop and nominal everywhere else"], badCaption: "'Zero retention' is claimed because the model provider doesn't store data, while the wrapper's own logging proxy writes full prompt and completion bodies and the client history persists the payload. The enterprise buyer routes sensitive data through it, unaware.", goodCaption: "Trace every hop and hold the boundary end to end: metadata-only proxy logs, no full-payload client history. 'Zero retention' has to be true at each write, not just the last one." },
  "systems-state-design-mm-0": { archetype: 'toggle-fix', subject: "Linear · Issue row", badLabel: "Three loose booleans", goodLabel: "One sync status", badLines: ["isLoading: true", "isSyncing: true", "hasEdits: true (unsaved text)", "→ Row renders a spinner ON TOP of text you just edited"], goodLines: ["status: 'edited-offline'", "→ Shows 'Saved locally, will sync' next to your text", "status: 'synced' → quiet check, no spinner", "Spinner-over-edited-text is now unrepresentable"], badCaption: "Loose booleans let loading, syncing and unsaved-edit all be true at once, so the save indicator spins forever next to text that already saved and users stop believing it.", goodCaption: "A single status enum is in exactly one situation at a time, so the spinner-on-fresh-edit combination cannot render." },
  "systems-state-design-mm-1": { archetype: 'toggle-fix', subject: "Stripe Dashboard · Charge detail", badLabel: "4 independent flags", goodLabel: "status enum", badLines: ["succeeded: true, failed: true", "receipt_url + decline_code both present", "→ Declined charge shows a receipt link", "→ Successful charge shows a decline reason"], goodLines: ["status: 'succeeded' → receipt only", "status: 'failed' → decline_code only", "status: 'requires_action' → next-step link", "The wrong field literally does not exist on the case"], badCaption: "Flat booleans keep receipt and decline fields present on every charge, so a declined payment renders a receipt link when someone forgets a guard.", goodCaption: "A discriminated union carries only the fields its case can have, so a failed charge has no receipt field to leak." },
  "systems-state-design-mm-2": { archetype: 'before-after', subject: "Notion · New database, first login", badLabel: "Ideal state only", goodLabel: "All five states designed", badLines: ["First login → blank white page", "No rows, no guidance, no skeleton", "Sync fails → same blank page", "New user reads 'broken' and leaves"], goodLines: ["Empty: 'Add your first row' with a starter", "Loading: table skeleton, not a void", "Error: 'Couldn't sync' banner with retry", "Each personality designed, not defaulted"], badCaption: "Designing only the Ideal state leaves Empty, Loading and Error as a bare white page, which reads as broken at the exact moment a new user decides whether to trust the product.", goodCaption: "Ideal, Empty, Error, Partial and Loading are each designed, so first use teaches instead of alarming." },
  "systems-state-design-mm-3": { archetype: 'toggle-fix', subject: "Coinbase · Send crypto", badLabel: "Optimistic (like a like button)", goodLabel: "Truthful confirmation ladder", badLines: ["Tap Send → balance instantly zeroes", "Recipient shown as credited", "Network rejects → balance silently reverts", "Indistinguishable from theft or a bug"], goodLines: ["Tap Send → 'Pending · 0 of 3 confirmations'", "Balance held, not zeroed, until finality", "Ladder advances to 'Confirmed' visibly", "No finality implied before it exists"], badCaption: "Optimistically crediting an irreversible transfer before finality means a silent revert looks, from the user's seat, exactly like a theft or a bug.", goodCaption: "A visible pending-to-confirmed ladder only shows finality the transfer actually has." },
  "systems-state-design-mm-4": { archetype: 'sequence', badSequence: ["Tap Buy", "UI goes dead, fill lags behind the delay", "No 'order received', nothing moves", "User re-taps Buy 3 more times", "Fill resolves → 4 duplicate orders"], goodSequence: ["Tap Buy", "Instant 'Order received · pending' state", "Delay acknowledged on screen", "Buy button locked while in-flight", "One fill confirmed"], badCaption: "A UI that goes dead during the confirmation delay trains panic re-clicking, which becomes real duplicate orders when nothing locks the in-flight request.", goodCaption: "Immediate pending feedback matched to the delay closes the loop, so the user waits instead of firing three more orders." },
  "systems-state-design-mm-5": { archetype: 'sequence', badSequence: ["Queued", "Building…", "Build hangs past the limit", "(no timeout edge is drawn)", "Still 'Building…' hours later"], goodSequence: ["Queued", "Building…", "timeout edge fires at the limit", "Failed: 'Build exceeded 45m, stopped'", "Reason shown, retry available"], badCaption: "Omitting the timeout edge leaves a stuck build spinning 'Building...' for hours, so the user can't tell a slow build from a dead one.", goodCaption: "A named timeout edge turns a hung build into a failed state with a reason and a retry." },
  "systems-state-design-mm-6": { archetype: 'reveal', subject: "Figma · Button component vs coded states", opaqueLabel: "Designed variants: Default · Hover · Loading · Disabled", revealedLines: ["Reducer also has: 'reconnecting'", "No Figma variant was ever drawn for it", "Ships with default styling, looks broken", "Never appeared in a single design review", "Code Connect exists to keep the maps 1:1"], badCaption: "When the reducer has a reconnecting state the design system never drew, it ships unstyled and nobody in design review ever saw it.", goodCaption: "Design-state and implementation-state are one machine, so every reducer case has a drawn variant and the divergence surfaces before shipping." },
  "systems-state-design-pat-0": { archetype: 'slider-map', sliderLabel: "Background refetch of data you already have", outputLabel: "What the screen shows", badCaption: "Deriving UI from isLoading OR isFetching blanks the screen to a full spinner over data you already have on every background refresh.", goodCaption: "Splitting status from fetchStatus lets a refetch keep showing data with just an 'updating' cue." },
  "systems-state-design-pat-1": { archetype: 'sequence', badSequence: ["idle", "pairing → session-proposal", "session expires while proposal is open", "APPROVE fires anyway (nothing blocks it)", "Approved a session that already expired"], goodSequence: ["idle → pairing → session-proposal", "expiry edge moves machine to 'expired'", "APPROVE has no edge from 'expired'", "Event is dropped, not applied", "Guarded chart makes the race impossible"], badCaption: "A boolean connection flow hits the 'approved a session that already expired' race because nothing stops the APPROVE event from firing in the expired state.", goodCaption: "A guarded statechart only accepts APPROVE from states where an edge exists, so the expired-approval race can't occur." },
  "systems-state-design-pat-2": { archetype: 'toggle-fix', subject: "Vercel Analytics · Metric tile", badLabel: "One loading flag", goodLabel: "Two-axis: hasData × isFetching", badLines: ["isLoading drives the whole tile", "Every 10s poll flips it true", "→ Full spinner over the last value", "Working real-time view feels broken"], goodLines: ["hasData: true, isFetching: true", "→ Last value shown + refresh shimmer", "All four quadrants are renderable", "'Stale but refreshing' finally has a look"], badCaption: "Collapsing availability and freshness into one loading flag flashes a full spinner over data you already had every polling interval.", goodCaption: "Two independent axes let a tile show its last value with a shimmer while a refresh runs underneath." },
  "systems-state-design-pat-3": { archetype: 'toggle-fix', subject: "Linear · Mark issue done", badLabel: "Optimistic, no rollback", goodLabel: "Optimistic + visible rollback", badLines: ["Click Done → issue flips instantly", "Sync to server fails", "onError does nothing", "Board shows Done; server never updated"], goodLines: ["Click Done → issue flips instantly", "Sync fails → issue reverts to open", "Short notice: 'Couldn't save, retry'", "Board and server stay in agreement"], badCaption: "An optimistic write with no rollback path leaves the board showing Done on an issue the server never updated, so board and reality quietly diverge.", goodCaption: "Reconciling on failure reverts the change with a clear notice instead of leaving the UI silently wrong." },
  "systems-state-design-pat-4": { archetype: 'sequence', badSequence: ["submitted", "pending… (only state modeled)", "gas too low, tx stuck", "No speed-up, no cancel offered", "User stranded, can't tell dropped from slow"], goodSequence: ["submitted → pending → confirmed → finalized", "pending is a real, distinct rung", "Speed-up + Cancel reachable from pending", "Nonce replacement escapes a stuck tx", "failed and dropped are their own states"], badCaption: "Showing only 'pending...' with no escape hatch strands users on a stuck low-gas transaction with no way to speed it up or cancel and no way to tell dropped from slow.", goodCaption: "Modeling each rung distinctly makes speed-up and cancel actions reachable only from pending, where they belong." },
  "systems-state-design-pat-5": { archetype: 'sequence', badSequence: ["Ask question", "Spinner…", "Spinner… (second 8)", "User can't tell work from an infinite loop", "Abandoned before the answer lands"], goodSequence: ["Searching 12 sources", "Reading top 4 results", "Comparing findings", "Drafting the answer", "Reads as 'working through it', not frozen"], badCaption: "A bare spinner on a 40-second run gets abandoned at second 8 because the user can't distinguish productive work from an infinite loop.", goodCaption: "Streaming the real trajectory as verb-object-result steps makes a long run read as visible progress." },
  "systems-state-design-pat-6": { archetype: 'sequence', badSequence: ["Agent mid-edit on a file", "User hits Cancel", "Process is hard-killed", "Half-written file, half-run tool call left", "'Stop' is scarier than 'let it finish'"], goodSequence: ["Agent mid-edit on a file", "User hits Cancel", "Machine enters modeled 'cancelling' state", "Runs defined cleanup to a coherent point", "Stops at a checkpoint you can resume from"], badCaption: "When cancel just kills the process it leaves half-written files and half-run tool calls, so 'stop' becomes scarier than letting it finish, the opposite of control.", goodCaption: "Pause, resume and cancel as first-class states with defined cleanup stop the agent at a coherent, resumable checkpoint." },
  "systems-state-design-pat-7": { archetype: 'sequence', badSequence: ["Read file → confirm?", "List directory → confirm?", "Run tests → confirm?", "Blanket-approve reflex sets in (~93%)", "rm -rf waved through with the rest"], goodSequence: ["Read file → auto-runs, low risk", "List directory → auto-runs", "Edit file → asks inline, medium risk", "Delete git history → hard block, high risk", "Attention spent where consequences live"], badCaption: "Confirming every action trains the blanket-approve reflex Anthropic measured at ~93%, so the one dangerous action is dismissed as fast as the trivial ones.", goodCaption: "Routing by risk tier auto-runs the reversible and hard-gates the destructive, keeping approval attention for what matters." },
  "systems-state-design-pat-8": { archetype: 'reveal', subject: "Shopify Polaris · Component state contract", opaqueLabel: "Stories: Default · Loading · Error · Disabled", revealedLines: ["Reducer adds a 'reconnecting' state", "No story renders it", "Red gap opens in the state grid", "'partial-error' also never rendered", "First person to hit it is a production user"], badCaption: "Without a story-per-state contract, a 'partial-error' or 'disabled-loading' state is never rendered until a real user hits it in production.", goodCaption: "One story per legal state makes the story set the executable contract, so an uncovered state shows up as a visible gap." },
  "systems-state-design-anti-0": { archetype: 'toggle-fix', subject: "Firebase · Data component", badLabel: "Boolean soup (3 hooks)", goodLabel: "Single status field", badLines: ["loading: true", "error: true", "value: (stale) present", "→ Spinner + error + stale data at once"], goodLines: ["status: 'refetching-stale'", "One field names the exact situation", "'This is old' becomes expressible", "The 3-true combination can't be reached"], badCaption: "Three independent hooks let a slow reconnect show stale value while loading is also true with no way to say 'this is old,' so the screen renders a spinner over data.", goodCaption: "A single status field collapses the 2^N combinations to the few legal ones and gives staleness a name." },
  "systems-state-design-anti-1": { archetype: 'before-after', subject: "Jira · Board, first login", badLabel: "Happy-path clone", goodLabel: "Designed empty state", badLines: ["New team logs in", "Board shows a blank column", "No guidance, no next action", "40-60% read it as 'broken' and bounce"], goodLines: ["Board shows a designed empty state", "'Create your first issue' with a button", "Explains what a column is for", "Onboarding, not a suspected outage"], badCaption: "Shipping only the Ideal state leaves a blank column on first login, which 40-60% of trial users read as 'nothing here / broken' while deciding whether to stay.", goodCaption: "A designed empty state teaches the new team how to create their first issue at the moment that decides the trial." },
  "systems-state-design-anti-3": { archetype: 'toggle-fix', subject: "Uniswap · Token swap", badLabel: "Optimistic, silent revert", goodLabel: "Reconcile with explanation", badLines: ["Swap shows 'Complete', balance credited", "Tx fails on-chain", "Balance silently reverts", "User believes they hold tokens they never got"], goodLines: ["Swap shows 'Pending' until on-chain result", "Tx fails → 'Swap failed: reverted on-chain'", "Balance never falsely credited", "Failure named, not a silent drop"], badCaption: "For financial state a silent revert is indistinguishable from theft or a bug, so the user can't tell 'the network rejected this' from 'someone took my money.'", goodCaption: "Holding the balance until the on-chain result and naming a failure repays the optimistic loan visibly." },
  "systems-state-design-anti-4": { archetype: 'toggle-fix', subject: "CoinGecko · Price widget", badLabel: "No freshness cue", goodLabel: "'As of' timestamp + stale flag", badLines: ["Feed drops silently", "Widget keeps showing last fetched price", "Looks identical to a live price", "User trades against a minutes-stale number"], goodLines: ["$63,214", "'Last updated 43s ago'", "Stale badge once the feed is frozen", "The lie becomes visible before the trade"], badCaption: "Rendering the last-known price with no freshness signal in a real-time context lets a user place a trade against a number that's minutes stale, a direct loss.", goodCaption: "An 'as of' stamp and a stale flag make a frozen feed obvious before the user acts on it." },
  "systems-state-design-anti-5": { archetype: 'toggle-fix', subject: "Airtable · New base panel", badLabel: "One blank panel for all three", goodLabel: "Three distinct states", badLines: ["No rows yet → gray nothing", "Failed sync → same gray nothing", "Slow load → same gray nothing", "First-timer assumes broken"], goodLines: ["Empty → 'Add your first record' (create)", "Error → 'Couldn't load' (retry)", "Loading → skeleton (wait)", "Three states, three actions"], badCaption: "Collapsing 'no data yet', 'couldn't load' and 'still loading' into one blank panel means a first-timer can't tell empty from broken and assumes broken.", goodCaption: "Distinct visuals with distinct actions, create, retry, wait, separate onboarding from an outage." },
  "systems-state-design-anti-6": { archetype: 'toggle-fix', subject: "GitHub · Failed action", badLabel: "Toast-only error", goodLabel: "Error as persistent state", badLines: ["Save fails", "3-second toast fires", "User glances away, toast vanishes", "Screen looks normal; they believe it saved"], goodLines: ["Save fails", "Persistent banner with the reason", "Retry action stays on screen", "Failure remains actionable until resolved"], badCaption: "Firing a failure as a toast that vanishes leaves the screen looking normal, so the user glances away believing their work saved and discovers the loss much later.", goodCaption: "Treating the error as a state keeps a persistent banner with the reason and a retry until the user handles it." },
  "systems-state-design-anti-7": { archetype: 'reveal', subject: "Slack · Real-time connection states", opaqueLabel: "Designed states: Online · Away · Offline", revealedLines: ["Reducer also runs: 'reconnecting'", "and 'partial-error' on flaky networks", "Neither was ever designed", "Both render as unstyled orphans", "Users hit them exactly when the network is bad"], badCaption: "Reconnecting and partial-error are the states users hit on flaky networks, so an undesigned subset makes the product feel unpolished precisely under real conditions.", goodCaption: "Designing the reconnecting state real-time apps actually enter keeps the product styled when connections drop." },
  "systems-state-design-anti-8": { archetype: 'sequence', badSequence: ["Click Pay", "'Submitting' doesn't disable the button", "Long confirmation delay", "User re-clicks 3 times", "N charges, N orders created"], goodSequence: ["Click Pay", "Button disables on submit", "Idempotency key attached", "Repeat clicks absorbed", "Exactly one charge, one order"], badCaption: "A submitting state that doesn't disable the button or absorb repeats produces real double-charges when the network is slow, born from one missing in-flight lock.", goodCaption: "Disabling on submit plus an idempotency key folds every extra click into a single charge." },
  "systems-state-design-inv-0": { archetype: 'sequence', badSequence: ["Fire metadata API call", "reducer handles success", "reducer handles error", "no branch for 'never resolved'", "One hung call spins the whole panel until reload"], goodSequence: ["Fire metadata API call", "success and error handled", "timeout edge added", "hang → 'Request timed out, retry'", "Hang becomes a recoverable error"], badCaption: "A reducer with only success and error cases has no branch for a request that never resolves, so a single hung call leaves a whole panel spinning until the user reloads.", goodCaption: "A timeout edge turns a hung API call into 'timed out, retry' and tells a slow region from a dead one." },
  "systems-state-design-inv-1": { archetype: 'toggle-fix', subject: "Redux slice · { loading, error, data }", badLabel: "3 independent keys", goodLabel: "One discriminated union", badLines: ["loading: true, error: true, data: present", "No action prevents this combination", "→ error rendered over content", "Intermittent, hard-to-reproduce glitches"], goodLines: ["state: { status: 'error', message }", "or { status: 'success', data }", "loading && error is unrepresentable", "Illegal rows never reachable"], badCaption: "Separate loading, error and data keys permit loading && error && data at once, an illegal-but-reachable combo that surfaces as intermittent glitches that eat debugging days.", goodCaption: "A discriminated union makes the illegal combinations impossible to construct, so the glitch class disappears at the root." },
  "systems-state-design-inv-2": { archetype: 'toggle-fix', subject: "Grafana · Metric panel (incident)", badLabel: "Hides dataUpdatedAt", goodLabel: "Exposes dataUpdatedAt", badLines: ["Panel reads from stale-while-revalidate cache", "Feed froze 5 minutes ago", "Number looks exactly like a live one", "SRE makes the wrong call on dead data"], goodLines: ["Same cached number", "'Updated 2m ago' shown under it", "Stale flag once the source stops", "Engineer sees the feed is frozen"], badCaption: "With no freshness indicator an engineer trusts a metric that stopped updating 5 minutes ago and makes the wrong call, and nothing on screen told them the feed had frozen.", goodCaption: "Exposing dataUpdatedAt shows the value's age and flags staleness, so no one acts on a dead feed during an incident." },
  "systems-state-design-inv-3": { archetype: 'toggle-fix', subject: "Trello · Drag a card between columns", badLabel: "onError does nothing", goodLabel: "onError reverts + notifies", badLines: ["Drag card → lands instantly", "Server rejects the move", "Handler has no revert", "Card stays wrong; board and server diverge"], goodLines: ["Drag card → lands instantly", "Server rejects the move", "Card reverts to its original column", "'Move didn't save' notice shown"], badCaption: "An optimistic move with an empty onError leaves the card in the wrong column while the backend disagrees, so a teammate on the same board sees a different reality.", goodCaption: "Reverting the card and notifying on rejection keeps the board and the server in agreement." },
  "systems-state-design-inv-4": { archetype: 'toggle-fix', subject: "Gmail · Send failure", badLabel: "Error as a toast", goodLabel: "Error written to state", badLines: ["Send fails", "catch fires a 3s toast", "Screen returns to 'sent-looking'", "User believes an important email went out"], goodLines: ["Send fails", "Persistent 'Message not sent' banner", "Resend action stays available", "Failure can't be missed"], badCaption: "A toast-only send failure lets the user believe an important email went out; the ambiguity isn't discovered until the recipient asks why they never got it.", goodCaption: "Writing the failure to state keeps a persistent 'not sent' banner with resend until it actually goes." },
  "systems-state-design-inv-5": { archetype: 'sequence', badSequence: ["Click Buy Now", "No immediate pending feedback (400ms gap)", "Slow connection, button looks dead", "User clicks again during the gap", "Duplicate orders placed"], goodSequence: ["Click Buy Now", "Button flips to disabled 'Processing' instantly", "Feedback loop closed before doubt sets in", "Second click has nothing to hit", "One order placed"], badCaption: "A button with no immediate pending feedback gets clicked again during the delay on a slow connection, and with no in-flight lock that becomes duplicate orders.", goodCaption: "Rendering the disabled 'processing' state the instant it's clicked closes the loop before the user can suspect a dead click." },
  "systems-state-design-inv-7": { archetype: 'toggle-fix', subject: "Binance · Order book / price stream", badLabel: "No connection state", goodLabel: "Reconnecting badge", badLines: ["Socket drops", "Numbers just stop updating", "Frozen book looks exactly like a live one", "Trader places orders against prices that are gone"], goodLines: ["Socket drops", "'Reconnecting…' badge appears", "Frozen book is visibly flagged", "Trader knows not to act on it"], badCaption: "A trader acting on a frozen order book that looks live places orders against prices that no longer exist, a direct loss caused entirely by a missing connection cue.", goodCaption: "A reconnecting badge makes the freeze obvious, so no one trades against a dead stream." },
  "systems-state-design-inv-8": { archetype: 'sequence', badSequence: ["Start task", "Bare spinner…", "Agent stuck in a repeating-tool loop", "Spinner looks the same as real work", "User cancels the first slow run; trust dies"], goodSequence: ["Start task", "Live plan + each command shown", "Step feed: verb + object + result", "The repeating-tool loop is visible", "5-minute task reads as progress"], badCaption: "On the first slow run a spinner-only agent gets cancelled because the user can't distinguish work from a hang, and that single cancellation is often where trust dies.", goodCaption: "A live step feed of verb-object-result makes progress legible and exposes a repeating-tool loop the spinner hid." },
  "systems-state-design-inv-9": { archetype: 'toggle-fix', subject: "MetaMask · Token send vs settings toggle", badLabel: "Send treated like a 'like'", goodLabel: "Risk-tiered", badLines: ["'Send 2 ETH' fires on one instant tap", "Same reflex pattern as a UI toggle", "No confirmation, no finality ladder", "Irreversible transfer fired before judgment engages"], goodLines: ["'Send 2 ETH' → distinct confirmation step", "pending-vs-confirmed finality ladder", "Reversible toggles stay one-tap", "Gate scaled to consequence"], badCaption: "Collapsing an irreversible send into the same instant pattern as a settings toggle lets users commit funds with a reflex tap before engaging their judgment, and there's no undo.", goodCaption: "Risk-tiering adds a confirmation step and a finality ladder only to the irreversible action, leaving the reversible one instant." },
  "data-heavy-screens-mm-0": { archetype: 'slider-map', sliderLabel: "Chrome (gridlines, borders, shadows)", outputLabel: "Data-pixels vs chrome-pixels", badCaption: "Heavy panel borders, full-opacity gridlines, and swatch legend boxes eat the pixels an on-call engineer scans mid-incident.", goodCaption: "Fade the chrome to zero and the data lines stay put; every remaining pixel carries a reading, so the trend reads at a glance." },
  "data-heavy-screens-mm-1": { archetype: 'before-after', subject: "Stripe payments view", badLabel: "Five encodings per metric", goodLabel: "One encoding", badLines: ["Net volume  $48,120  ↑ +3.2%  ▸▸▸ (sparkline)  green heat-tint row", "MRR  $12,300  ↑ +1.1%  ▸▸▸ (sparkline)  green heat-tint row", "Refunds  $2,040  ↓ -0.4%  ▾▾▾ (sparkline)  red heat-tint row"], goodLines: ["Net volume  $48,120  +3.2%", "MRR  $12,300  +1.1%", "Refunds  $2,040  -0.4%"], badCaption: "Sparkline, arrow, delta, and heat-tint all encode the same one movement, so scanning for the anomalous number burns budget rejecting three redundant signals per row.", goodCaption: "One encoding per fact leaves the finance user's attention free for the single number that actually moved." },
  "data-heavy-screens-mm-2": { archetype: 'before-after', subject: "PagerDuty incident list", badLabel: "Every severity a saturated color", goodLabel: "Gray all but open SEV-1", badLines: ["SEV-3  API latency elevated  (yellow)", "SEV-2  Cache eviction spike  (orange)", "SEV-1  Checkout down  (red)", "SEV-4  Log volume drift  (blue)", "SEV-3  Retry storm  (purple)"], goodLines: ["SEV-3  API latency elevated  (gray)", "SEV-2  Cache eviction spike  (gray)", "SEV-1  Checkout down  (red)", "SEV-4  Log volume drift  (gray)", "SEV-3  Retry storm  (gray)"], badCaption: "The one SEV-1 that should pop in 250ms is buried in a rainbow of oranges, yellows, blues, and purples, so triage degrades into serial reading.", goodCaption: "Gray everything except open SEV-1s and the critical row is found preattentively, before conscious attention even engages." },
  "data-heavy-screens-mm-3": { archetype: 'before-after', subject: "Vercel Analytics: LCP across routes", badLabel: "One overlaid line chart", goodLabel: "Small-multiples grid, shared scale", badLines: ["12 route LCP lines overlaid on one axis", "Colors collide into spaghetti", "Legend hunt to match line to route", "The one diverging route hides in the tangle"], goodLines: ["/  ▁▂▂▁ ok", "/pricing  ▁▂▃▂ ok", "/blog  ▁▁▂▁ ok", "/checkout  ▃▅▇█ diverging", "one panel per route, one shared y-axis"], badCaption: "Twelve routes overlaid is unreadable spaghetti and forces legend hunting to tell teal from cyan.", goodCaption: "Faceted panels on a shared scale let a developer spot the one route whose LCP diverges in a single pass." },
  "data-heavy-screens-mm-4": { archetype: 'before-after', subject: "Linear issue list", badLabel: "Simplified: big cards, whitespace", goodLabel: "Dense: many rows, no decoration", badLines: ["ENG-482  Fix auth redirect        (one big card)", "ENG-483  Rate-limit uploads       (one big card)", "3 issues fill the screen; chrome per issue is high"], goodLines: ["ENG-482  Fix auth redirect      P1  In Progress  @sam  auth", "ENG-483  Rate-limit uploads     P2  Todo         @lee  api", "ENG-484  Cache invalidation     P3  Backlog      @kim  perf", "ENG-485  Empty-state copy       P2  In Review    @ana  ui", "20 issues fit; every mark carries meaning"], badCaption: "'Simplifying' with whitespace and big cards shows fewer issues per screen and more chrome per issue; the working surface shrinks.", goodCaption: "Dense reads calmly when nothing is decorative; density plus zero clutter is what won Linear its power users." },
  "data-heavy-screens-mm-5": { archetype: 'meter', headline: "Avg session length +12% QoQ", breakdown: [{ label: "Power users (returning)", value: -18 }, { label: "Mid-tenure users", value: -6 }, { label: "New shallow signups (share grew)", value: -22 }], badCaption: "The headline mean said growth, so the team celebrated; the roll-up threw away the distribution underneath it.", goodCaption: "Split by cohort and every segment is falling: power users are churning and a flood of shallow signups dragged the composition. The distribution reverses the story." },
  "data-heavy-screens-mm-6": { archetype: 'toggle-fix', subject: "Notion filtered database view", badLabel: "One blank for every state", goodLabel: "Five distinct states, five CTAs", badLines: ["(empty gray panel)", "Loading, empty, zero, error, and filtered-out all render identically", "User thinks their data vanished and panics"], goodLines: ["Loading: skeleton rows", "Empty: 'No pages yet - Add a page'", "Zero: 'Count = 0 for this view'", "Error: 'Sync failed - Retry'", "Filtered: 'Filter hides all 240 rows - Clear filter'"], badCaption: "A filter that excludes every row renders identical to a brand-new empty database and to a failed sync, so the user panics or files a broken-feature ticket.", goodCaption: "Each state gets its own face and its own CTA, so the fix is one visible click: clear the filter chip." },
  "data-heavy-screens-mm-7": { archetype: 'toggle-fix', subject: "Coinbase portfolio table", badLabel: "Proportional, left-aligned", goodLabel: "Tabular, right-aligned", badLines: ["BTC   0.0041", "ETH   1.2000", "SOL   14.5", "USDC  1204.3378", "decimals do not line up; largest position not obvious"], goodLines: ["BTC        0.0041", "ETH        1.2000", "SOL       14.5000", "USDC   1,204.3378", "decimals align; tallest column is the largest, instantly"], badCaption: "Proportional figures left-aligned mean 0.0041 and 1.2000 never line up on the decimal, so a trader reads every number instead of seeing the tallest column.", goodCaption: "Tabular figures right-aligned on the decimal make magnitude a matter of column height; the largest position is seen, not read." },
  "data-heavy-screens-pat-0": { archetype: 'toggle-fix', subject: "Bloomberg Terminal numeric grid", badLabel: "Proportional, ragged precision, left-aligned", goodLabel: "Monospaced, fixed precision, right-aligned", badLines: ["AAPL  189.4  +1.23", "MSFT  412.06  +0.9", "NVDA  1204.338  +11.2", "widths jump, decimals wander, precision varies per row"], goodLines: ["AAPL    189.40   +1.23", "MSFT    412.06   +0.90", "NVDA  1,204.34  +11.20", "fixed-width digits, one precision per column, aligned"], badCaption: "Drop tabular figures, consistent precision, or right alignment and the dense grid stops being scannable for the users who read it at a glance.", goodCaption: "Monospaced, right-aligned, fixed-precision-per-column is the reference standard: the alignment is exactly what makes the density usable." },
  "data-heavy-screens-pat-1": { archetype: 'before-after', subject: "Vercel deployments table", badLabel: "No trend context", goodLabel: "In-row traffic sparklines", badLines: ["acme-web       Ready   click in to see traffic", "docs-site      Ready   click in to see traffic", "api-gateway    Ready   click in to see traffic", "spotting the spiking project means opening a dozen charts"], goodLines: ["acme-web       Ready   ▁▁▂▁▁", "docs-site      Ready   ▁▂▁▂▁", "api-gateway    Ready   ▂▃▅▇█ spiking", "the anomalous project shows its shape in one scan"], badCaption: "Without an inline shape, finding the one project with anomalous traffic means clicking into a dozen full charts, a serial drill-down.", goodCaption: "A word-sized sparkline per row turns that drill-down into a single scan of the column; the spiking project's shape is right there." },
  "data-heavy-screens-pat-2": { archetype: 'before-after', subject: "Grafana: latency across 20 services", badLabel: "One 20-line overlaid chart", goodLabel: "Repeat-panel small multiples, shared axis", badLines: ["20 services overlaid on one p99 chart", "lines cross, colors merge", "legend the size of the panel", "the one spiked service is invisible"], goodLines: ["auth      ▁▂▁  ok", "cart      ▁▁▂  ok", "search    ▁▂▃  ok", "payments  ▅▇█  p99 spiked", "20 mini-graphs, one shared y-axis, sorted"], badCaption: "The overlaid version is unreadable spaghetti during exactly the incident an SRE needs it.", goodCaption: "Repeat-panel-by-service on a shared axis lets the SRE spot the one service whose p99 spiked in a single pass." },
  "data-heavy-screens-pat-3": { archetype: 'before-after', subject: "Salesforce quota-attainment dashboard", badLabel: "Circular gauges", goodLabel: "Bullet graphs, stacked", badLines: ["Rep A: one big needle gauge, 78%", "Rep B: one big needle gauge, 64% (scroll to compare)", "one metric per giant widget; comparing reps means scrolling"], goodLines: ["Rep A  ██████▉░  78% |target", "Rep B  █████░░░  64% |target", "Rep C  ███████▉  92% |target", "ten reps, actual-vs-quota-vs-bands, one screen"], badCaption: "Gauges force one metric per giant widget and scrolling to compare reps; the circle wastes area to show a single number.", goodCaption: "Bullet graphs stack ten reps in the space one gauge used, each showing actual against quota and qualitative bands at a glance." },
  "data-heavy-screens-pat-4": { archetype: 'toggle-fix', subject: "Airtable wide grid", badLabel: "Nothing frozen", goodLabel: "Header + primary column frozen", badLines: ["scroll right past dozens of fields", "field headers scroll away", "primary-field column scrolls away", "values with no idea which record they belong to"], goodLines: ["field headers stay pinned across the top", "primary-field column stays pinned on the left", "row highlight follows the cursor", "every value keeps its record identity while scrolling"], badCaption: "Scroll right on a wide base with nothing pinned and you are looking at values with no idea which record they belong to.", goodCaption: "Freeze the header row and the primary column and a very wide table becomes navigable; every cell keeps its identity." },
  "data-heavy-screens-pat-5": { archetype: 'toggle-fix', subject: "Linear filtered issue view", badLabel: "Hidden default filter", goodLabel: "Active filters as removable chips", badLines: ["persisted filter silently scopes the view", "0 issues shown, no reason given", "'my issues disappeared'", "no way to see what is hiding them"], goodLines: ["Chips: [assignee: @you ×] [status: In Progress ×] [label: bug ×]", "4 results · Clear all", "empty view says which filters caused it", "remove one chip and the rows return"], badCaption: "A persisted default filter hides rows and the user thinks 'my issues disappeared' with no way to see what scoped the view.", goodCaption: "Surfacing active filters as removable chips with a live count and reset turns a panic into a one-click fix." },
  "data-heavy-screens-pat-6": { archetype: 'toggle-fix', subject: "Sentry issues view", badLabel: "One blank for every state", goodLabel: "Five distinct states", badLines: ["(blank panel)", "'no errors yet' and 'failed to load errors' render the same", "for an error monitor these mean opposite things"], goodLines: ["No errors yet: 'Nothing broke - nice'", "No results: 'No issues match this search'", "Error: 'Failed to load - Retry'", "Loading: skeleton rows", "each state has its own copy and CTA"], badCaption: "Collapsing 'no errors' (good) and 'failed to load errors' (bad) into one blank is dangerous for a monitoring tool: they mean opposite things.", goodCaption: "Rendering loading, empty, no-results, and error distinctly lets a user act on the difference instead of guessing." },
  "data-heavy-screens-pat-7": { archetype: 'toggle-fix', subject: "Datadog timeseries chart", badLabel: "Bottom color legend", goodLabel: "End-of-line labels", badLines: ["four lines: teal, cyan, blue, navy", "legend below: match swatch to name", "eye leaves the data, matches color, travels back", "teal vs cyan misread in dark mode"], goodLines: ["p50 ------------ 120ms", "p75 ------------ 210ms", "p95 ------------ 480ms", "p99 ------------ 1.4s", "each label sits at the end of its own line"], badCaption: "A color legend forces the eye to leave the data and match teal against cyan against a name, error-prone especially in dark mode.", goodCaption: "Labeling each line at its right edge removes the lookup and the color confusion; 'what was p99's final value' is answered where you're already looking." },
  "data-heavy-screens-pat-8": { archetype: 'toggle-fix', subject: "Robinhood positions screen", badLabel: "Color everything", goodLabel: "Color only P/L sign", badLines: ["AAPL  +$42  (green ticker, green sector, green button)", "TSLA  -$88  (red among many reds)", "NVDA  +$210 (green among many greens)", "the one losing position is camouflaged"], goodLines: ["AAPL  +$42   (neutral row, green sign only)", "TSLA  -$88   (neutral row, red sign only)", "NVDA  +$210  (neutral row, green sign only)", "the losing positions pop against a gray field"], badCaption: "If gains, sectors, tickers, and buttons are all colored, the one red position a trader must act on is camouflaged.", goodCaption: "Keep the field neutral and spend color only on the P/L sign, and the losing positions are instantly visible." },
  "data-heavy-screens-anti-0": { archetype: 'before-after', subject: "DeFi protocol dashboard", badLabel: "Three glowing gauges", goodLabel: "Three bullet graphs", badLines: ["TVL:  circular needle gauge, red/green zones", "APY:  circular needle gauge, red/green zones", "Health: circular needle gauge, red/green zones", "three numbers spread across the whole viewport; status by color only"], goodLines: ["TVL     ██████▉░  vs target", "APY     ████░░░░  vs target", "Health  ███████▉  vs bands", "compact, comparable, colorblind-safe"], badCaption: "TVL, APY, and health as three glowing needle gauges look like a spaceship and inform like a billboard: nothing comparable, status by color only, fails for colorblind users.", goodCaption: "Bullet graphs put all three metrics against targets and bands in a fraction of the space, comparable and readable without relying on hue." },
  "data-heavy-screens-anti-1": { archetype: 'slider-map', sliderLabel: "Colorfulness (saturate every cell)", outputLabel: "Time to find the critical red breach", badCaption: "Theme every panel, threshold, and series with saturated color and the one genuinely critical red breach sits among decorative reds and greens; on-call engineers miss the real alert.", goodCaption: "Strip color back to neutral and reserve it for the breach, and the critical cell pops preattentively instead of drowning." },
  "data-heavy-screens-anti-2": { archetype: 'toggle-fix', subject: "Notion number property column", badLabel: "Proportional, left-aligned", goodLabel: "Tabular, right-aligned", badLines: ["$1,240.50", "$88.10", "$1,204.34", "$9.99", "decimals wander; the column will not scan"], goodLines: ["  $1,240.50", "     $88.10", "  $1,204.34", "      $9.99", "decimals aligned; magnitude reads by column position"], badCaption: "A number property in the proportional UI font, left-aligned by default, makes a column of dollar amounts fail to line up on the decimal and read as sloppy.", goodCaption: "Right-aligned tabular figures line up the decimals so the eye compares magnitude by position instead of reading every cell." },
  "data-heavy-screens-anti-3": { archetype: 'toggle-fix', subject: "Binance live order book", badLabel: "Proportional font, full repaint", goodLabel: "Tabular font, stable digits", badLines: ["64,201.4  → 64,198.77  → 64,205.0", "column reflows on every tick", "digits strobe on full-cell repaint", "cannot lock onto a number that keeps jumping"], goodLines: ["64,201.40", "64,198.77", "64,205.00", "positions hold; only the changed digits update, no flicker"], badCaption: "A proportional-font ticker reflows the column on every tick and full-cell repaints strobe, so a trader cannot lock onto a fast-moving number and the feed reads as unstable.", goodCaption: "Tabular figures hold each digit's position and targeted repaints stop the strobe; the row stops twitching the moment tabular is on." },
  "data-heavy-screens-anti-4": { archetype: 'reveal', subject: "GA4 report", opaqueLabel: "Sessions: 128,540", revealedLines: ["Date range: last 28 days (default)", "Filter: exclude internal traffic (on)", "Data is sampled above threshold", "True unscoped total differs from the headline"], badCaption: "The headline number reads as absolute while a default 28-day window, an exclude-internal toggle, and sampling silently scope it with no on-screen cue, so people misreport it upward.", goodCaption: "Surface the active scope as chips beside the number and the reader sees the headline was conditional all along, and can remove it." },
  "data-heavy-screens-anti-5": { archetype: 'meter', headline: "Avg request time 200ms", breakdown: [{ label: "p50", value: 150 }, { label: "p90", value: 420 }, { label: "p99", value: 3200 }], badCaption: "The lone average sits at a healthy 200ms and hides the tail, so the team misses the p99 that is actually degrading real users' experience.", goodCaption: "Lead with percentiles and the long right tail appears: p99 at 3.2s is a different product than the mean implied." },
  "data-heavy-screens-anti-6": { archetype: 'toggle-fix', subject: "Retool query table component", badLabel: "Same blank for all five", goodLabel: "Five distinct states", badLines: ["(empty table / 'No data.')", "loading, zero rows, error, and filtered-out all look identical", "internal users file 'the tool is broken' tickets"], goodLines: ["Loading: skeleton rows", "Empty: 'No records yet'", "Zero: 'Query returned 0 rows'", "Error: 'Query failed - Retry' + message", "Filtered: 'Filter excluded all rows - Clear'"], badCaption: "Loading, empty, true-zero, filtered-out, and error all render as the same 'No data.', so internal users file 'the tool is broken' tickets on a query that is merely still running.", goodCaption: "Give each state a distinct skeleton, message, and action and the operator knows whether to wait, retry, or clear a filter." },
  "data-heavy-screens-anti-7": { archetype: 'before-after', subject: "Grafana per-pod latency panel", badLabel: "30+ overlaid lines", goodLabel: "Top-5 + others, or small multiples", badLines: ["metric graphed per-pod: 30+ lines overlaid", "lines cross, colors indistinguishable", "legend the size of the chart", "the one anomalous pod is hidden in the tangle"], goodLines: ["pod-7f2  ▅▇█  anomalous (top by value)", "pod-a19  ▁▂▁", "pod-c04  ▁▁▂", "pod-e88  ▂▁▂", "+ 26 others (collapsed)"], badCaption: "A high-cardinality per-pod label produces 30+ overlapping lines an on-call engineer cannot read during the incident when they most need it.", goodCaption: "Small multiples or top-k-plus-others makes the one anomalous series emerge from the tangle." },
  "data-heavy-screens-anti-8": { archetype: 'slider-map', sliderLabel: "Simplify (hide panels)", outputLabel: "Pro workflow surface remaining", badCaption: "'Simplifying' the terminal into big cards and one-metric screens hides the order book depth, timeframes, and position table pros relied on, and active traders leave.", goodCaption: "Keep the dense multi-panel layout: density was the product for that audience, so the working surface stays intact." },
  "data-heavy-screens-anti-9": { archetype: 'slider-map', sliderLabel: "Significant figures (10 → 3)", outputLabel: "Scan speed and column alignment", badCaption: "Showing 1,204.3378291043 USDC per row is unreadable, misaligns the column, implies precision nobody scanning a portfolio needs, and makes the displayed values not sum to the displayed total.", goodCaption: "Trim to three or four significant figures and scan speed and alignment both jump; the false precision was pure cost." },
  "data-heavy-screens-inv-0": { archetype: 'reveal', subject: "Metabase saved question", opaqueLabel: "Revenue: $412,900", revealedLines: ["WHERE created_at >= now() - interval '30 days'", "WHERE segment = 'enterprise'", "WHERE is_test = false", "Only one predicate is shown as a chip; two are invisible"], badCaption: "A saved question carries default WHERE clauses that scope every number on load but never render as visible chips, so a colleague reads the total as absolute and reports it wrong.", goodCaption: "Expose all three predicates from the query as visible filters and the reader sees the headline is conditional, not absolute." },
  "data-heavy-screens-inv-1": { archetype: 'meter', headline: "Overall conversion +4pts QoQ", breakdown: [{ label: "Paid search", value: -3 }, { label: "Organic", value: -2 }, { label: "Referral", value: -4 }, { label: "Email", value: -3 }], badCaption: "The headline conversion trends up, so the team celebrates and cuts the wrong channel; the aggregate rose only because a high-converting channel grew as a share of the mix.", goodCaption: "Segment by channel and every channel's conversion is falling: Simpson's paradox, invisible in the roll-up, visible the instant you split." },
  "data-heavy-screens-inv-2": { archetype: 'sequence', badSequence: ["fetch() resolves to null / [] / 200-empty / timeout / 0", "component maps all five outcomes to one branch", "render blank table", "developer cannot tell 'no rows' from 'RLS blocked' from 'still loading'", "a permissions bug becomes a phantom 'no data'"], goodSequence: ["fetch() resolves", "switch on outcome, not truthiness", "null/timeout → Error state with retry", "[] → Empty state; RLS-blocked → 'Access restricted'", "0 → true-zero; loading → skeleton"], badCaption: "null, empty array, a 200 with empty body, a timeout, and a genuine zero all map to one blank view, so an RLS permissions bug is indistinguishable from 'no data' and wastes debugging time.", goodCaption: "Branch on the actual outcome and each of the five renders a distinct state, so the developer sees whether rows were blocked, missing, loading, or truly zero." },
  "data-heavy-screens-inv-3": { archetype: 'sequence', badSequence: ["socket streams live price", "connection drops silently", "last price stays rendered, unchanged", "no 'last updated' or reconnect indicator", "user trades on a price minutes old, believing it live"], goodSequence: ["socket streams live price", "connection drops", "freshness clock keeps counting: 'updated 4s ago → 12s → 40s'", "'Reconnecting...' badge appears", "user sees the number is stale before acting"], badCaption: "When the socket drops the number just freezes and still looks real-time, so a user makes a trade decision on a price that is minutes old.", goodCaption: "A 'last updated Ns ago' clock and a reconnect badge expose the stall the moment the feed stops updating." },
  "data-heavy-screens-inv-4": { archetype: 'toggle-fix', subject: "QuickBooks line-item report", badLabel: "Round-then-sum", goodLabel: "Sum-then-round (or reconciled)", badLines: ["Item A   1.40", "Item B   1.40", "Item C   1.40", "Total    4.21   (rounds don't add to displayed rows)"], goodLines: ["Item A   1.40", "Item B   1.40", "Item C   1.40", "Total    4.20   (or a rounding line reconciling the 0.01)"], badCaption: "The UI rounds each line for display but computes the total from full precision, so the visible line items do not add up to the visible total and an accountant assumes the software is wrong.", goodCaption: "Reconcile the rounding so displayed rows sum to the displayed total; the credibility killer disappears." },
  "data-heavy-screens-inv-5": { archetype: 'toggle-fix', subject: "Vercel real-time requests/sec counter", badLabel: "Proportional figures", goodLabel: "tabular-nums", badLines: ["1.11k req/s  → 1.98k  → 842  → 1.20k", "digit count and shapes change width", "the metrics row reflows and twitches on every tick"], goodLines: ["1.11k req/s  → 1.98k  → 0.84k  → 1.20k", "every digit is fixed-width", "neighbors hold position; the row stays put"], badCaption: "Non-tabular digits change string width as the value updates, so changing 1.11 to 1.98 reflows neighboring cells and the metrics row twitches continuously; it ships because the design review used static values.", goodCaption: "One CSS property, tabular-nums, fixes every digit's width so the row stops shifting on each update." },
  "data-heavy-screens-inv-6": { archetype: 'sequence', badSequence: ["API returns page 1 (50 rows)", "operator clicks 'sort by amount'", "sort runs client-side on the 50 loaded rows", "top row shows the max of page 1, not overall", "the real largest orders on later pages never surface"], goodSequence: ["operator clicks 'sort by amount'", "request goes to the server: ORDER BY amount DESC", "server sorts the full dataset", "page 1 returns the true top rows", "the actual largest order is row one"], badCaption: "The table sorts only the 50 loaded rows in the browser, so 'top by amount' is just top-of-page-one and the real outliers on later pages are missed; the sorted page looks correct.", goodCaption: "Push the sort to the server so it orders the full dataset, and the true maximum actually appears in the top row." },
  "data-heavy-screens-inv-7": { archetype: 'toggle-fix', subject: "Robinhood P/L column", badLabel: "Color only", goodLabel: "Color + sign/arrow", badLines: ["$42.10   (green)", "$88.00   (red)", "$210.40  (green)", "in grayscale or for colorblind users these are identical"], goodLines: ["+$42.10  ↑", "-$88.00  ↓", "+$210.40 ↑", "the sign carries the meaning without relying on hue"], badCaption: "Daily gain/loss carried purely by red versus green, with no leading sign or arrow, is unreadable for red-green colorblind users (about 8% of men) and in any grayscale export.", goodCaption: "Add a redundant + / - and an arrow and gains and losses stay distinguishable without color at all." },
  "data-heavy-screens-inv-8": { archetype: 'before-after', subject: "TradingView price feed", badLabel: "Throttled, shown as tick-by-tick", goodLabel: "Raw high-frequency (or cadence labeled)", badLines: ["price updates every 1-2s for performance", "displayed as a continuously ticking number", "sharp intra-second wicks never appear", "trader misses the fast moves they trade on"], goodLines: ["raw feed ticks many times per second", "wicks and spikes are visible", "or: cadence labeled 'updates ~2s'", "the display no longer implies continuity it lacks"], badCaption: "A feed sampled every couple of seconds is presented as continuous tick-by-tick data, hiding the intra-window wicks a trader trades on.", goodCaption: "Show the raw high-frequency signal, or label the update cadence, so the display stops implying a continuity it never had." },
  "data-heavy-screens-inv-9": { archetype: 'toggle-fix', subject: "Etherscan value & timestamp column", badLabel: "No unit / zone labels", goodLabel: "Explicit unit + zone labels", badLines: ["Value  1204337829104000000", "Value  1.204", "Time   2026-07-14 09:12:04", "is that wei or ETH? UTC or local?"], goodLines: ["Value  1.2043 ETH  (1,204,337,829,104,000,000 wei)", "Value  1.204 ETH", "Time   2026-07-14 09:12:04 UTC  (2h ago local)", "unit and zone stated on every value"], badCaption: "Raw balances in wei sit beside amounts in ETH and UTC timestamps beside local relative times with no consistent labels, so a user misreads wei as ETH (off by 10^18) or misjudges when a transaction occurred.", goodCaption: "Label the unit and the zone on every value and the arithmetically-correct number is finally interpreted correctly." },
  "dashboards-entry-points-mm-0": { archetype: 'toggle-fix', subject: "Datadog host dashboard", badLabel: "Report mode", goodLabel: "Dashboard mode", badLines: ["40 graphs, equal-weight grid", "host.cpu   host.mem   host.net   ...", "scroll for 3 screens to find latency", "no tile says which service is down", "SLO status buried on row 5"], goodLines: ["checkout-svc p99: 840ms  BREACH", "one big tile, top-left, red", "3 supporting graphs below the fold", "everything fits one viewport, no scroll", "answer in under a second"], badCaption: "40 equal-weight tiles bury the one number that matters (is p99 past SLO right now), so triage moves to Slack and the dashboard gets skipped mid-incident.", goodCaption: "One question, one viewport, no scroll: the SLO breach is sized to dominate, so you read 'unhealthy' at a glance." },
  "dashboards-entry-points-mm-1": { archetype: 'sequence', badSequence: ["Load /payments", "Dump 10,000-row raw charge table", "Finance team scans columns for a total", "No trend, no orientation", "Give up, export to a spreadsheet"], goodSequence: ["Load: total volume + 7-day trend up top", "Filter by date range and status", "Spot the failed-charge spike", "Click one charge row", "Full event log opens in a side panel"], badCaption: "Skip the overview and finance drowns in a raw charge table on load: no total, no trend, no way in.", goodCaption: "Orient first (volume, trend), narrow (filter), then reveal one charge's full event log on demand: same screen serves the glance and the investigation." },
  "dashboards-entry-points-mm-2": { archetype: 'toggle-fix', subject: "Vercel project overview", badLabel: "Answers 3 questions", goodLabel: "Answers 1 question", badLines: ["Deploy status crammed top-left, 1/3 width", "Analytics charts fill the middle third", "Usage + billing meter on the right third", "Dev scans past 2 unrelated things first", "No section gets a clear answer"], goodLines: ["Latest deploy: Ready, commit 4a91c2", "Health check: 200 OK, 0 errors", "Deploy detail is the whole viewport", "Analytics and Logs are separate tabs", "Broken-deploy answer is immediate"], badCaption: "Merge deploys, analytics, and billing into one screen and a dev checking a broken deploy scans past two unrelated questions before finding the one they came for.", goodCaption: "The overview answers only 'is my deploy healthy'; analytics and logs live in their own tabs, so time-to-answer stays flat." },
  "dashboards-entry-points-mm-3": { archetype: 'toggle-fix', subject: "Linear issue board", badLabel: "Open gulfs", goodLabel: "Closes both gulfs", badLines: ["Set status to Done", "Toast: 'Updated'", "Card stays in the In Progress column", "No next action offered", "Did it save? Click in to check"], goodLines: ["Set status to Done", "Card animates into the Done column", "You see exactly what changed", "Assign / comment appear right there", "No second click to confirm"], badCaption: "A toast that says 'updated' while the card sits unchanged widens the evaluation gulf: the user can't see what happened and clicks in twice to be sure.", goodCaption: "The board re-reads state (card moves) and surfaces the next likely action inline, closing both the evaluation and execution gulf in one move." },
  "dashboards-entry-points-mm-4": { archetype: 'sequence', badSequence: ["Open settings tour", "Pick a model version", "Set aspect ratio, stylize, seed", "Read the parameter docs", "4 steps later, still no image"], goodSequence: ["Type /imagine a red fox in snow", "Hit enter", "Four images appear in under a minute", "Upscale or vary the one you like", "Tweak parameters after, if you want"], badCaption: "Front-load a 4-step config tour and users leak out admiring the camera settings instead of walking away with the win they came for.", goodCaption: "The win (I made an image) arrives before any tool mastery is required; parameters are there to tweak after the first result, not before it." },
  "dashboards-entry-points-mm-5": { archetype: 'toggle-fix', subject: "Notion sidebar navigation", badLabel: "Nav by org chart", goodLabel: "Nav by goal", badLines: ["Blocks Service", "Sync Engine", "Collaboration Backend", "Storage Layer", "user must learn Notion's internals first"], goodLines: ["Pages", "Databases", "Teamspaces", "Shared with me", "maps to how people think about their work"], badCaption: "A backend-mirrored nav exposes 'blocks service' and 'sync engine', forcing users to learn the company's structure before they can find anything.", goodCaption: "Navigation built from user artifacts (pages, databases, teamspaces) maps to real goals, which is why non-technical teams adopt it." },
  "dashboards-entry-points-mm-6": { archetype: 'before-after', subject: "PagerDuty on-call, 3am", badLabel: "Pull: watch the dashboard", goodLabel: "Push: incident to your phone", badLines: ["Grafana wall stays open on a monitor", "engineer has to be awake and looking", "one line ticks up among 30 charts", "no one translates the chart into a decision", "anomaly noticed 20 min late, if at all"], goodLines: ["Phone buzzes: SEV-2 incident", "Affected service: checkout-api", "p99 latency 3x baseline, 40% of users", "Runbook: restart-checkout-pool", "Acknowledge / Escalate right there"], badCaption: "A pull dashboard needs someone staring at it at 3am and still leaves them to translate a chart into a decision themselves.", goodCaption: "Push delivers the decision (severity, affected service, impact, runbook) at the moment and place the human can act, which is why it earns trust." },
  "dashboards-entry-points-mm-7": { archetype: 'reveal', subject: "MetaMask token approval", opaqueLabel: "Approve   [ Confirm ]", revealedLines: ["Spender: 0x9f2c... (unverified contract)", "Approved amount: UNLIMITED", "Can move any USDC, any time, forever", "Revoke only by a separate later tx", "Contract deployed 2 days ago"], badCaption: "A generic 'Confirm' hides that the default grant is unlimited spend, so users treat the connect step as a CTA and a malicious contract drains the allowance later.", goodCaption: "Decode the actual scope into consequences ('can move any amount, any time') before signing, so the first high-stakes action reads as the risk decision it is." },
  "dashboards-entry-points-pat-0": { archetype: 'reveal', subject: "Datadog APM service page", opaqueLabel: "Requests 1.2k/s   Errors 4.1%   p99 840ms", revealedLines: ["Tier 2: latency over time, last 4h", "Tier 2: errors by endpoint (POST /pay: 61%)", "Tier 3: individual traces table", "trace 7f3a: 812ms, DB call stalled", "each tier fetches only when opened"], badCaption: "Flatten a service page into one trace table and monitoring dies; flatten it into three big number panels and investigation is impossible.", goodCaption: "Tier 1 answers the glance (rate/errors/latency), tier 2 explains it, tier 3 holds the raw traces, each fetched only when revealed so first-paint cost stays flat." },
  "dashboards-entry-points-pat-1": { archetype: 'toggle-fix', subject: "GitHub repository view", badLabel: "Two separate pages", goodLabel: "Shared spine, role-conditioned actions", badLines: ["Maintainer sees a totally different repo page", "Contributor sees another layout entirely", "No shared tutorial works for both", "Cross-role screen-shares confuse", "'click the button' means two things"], goodLines: ["Same repo spine for everyone", "Maintainer: Merge + Settings promoted", "Contributor: Fork + Pull request primary", "Hidden modules absent from payload, not CSS-hidden", "One tutorial fits all"], badCaption: "Ship two entirely different repo pages and cross-role help breaks: no shared reference and no tutorial that fits both.", goodCaption: "One consistent spine everyone follows, with module order and the primary action conditioned on role, and gated modules truly absent from the payload." },
  "dashboards-entry-points-pat-2": { archetype: 'sequence', badSequence: ["Open the issue list", "Find the right issue by scrolling", "Click the issue to open it", "Open the assignee dropdown", "Search, then pick Sam"], goodSequence: ["Press Cmd+K", "Type 'assign sam'", "Fuzzy match surfaces the action", "Enter", "Done, without leaving your place"], badCaption: "Bury deep actions behind nav only and power users crawl; make the palette the only path and first-timers who don't know it exists bounce.", goodCaption: "Cmd+K is a findability safety net and an express lane, navigating and acting from the keyboard, while full visible nav stays for newcomers." },
  "dashboards-entry-points-pat-3": { archetype: 'toggle-fix', subject: "Gmail inbox triage", badLabel: "Full-page load per open", goodLabel: "Peek in a reading pane", badLines: ["Click a message", "Full-screen view loads", "Inbox scroll resets to top", "Archive, hit back", "Re-find your place, every time"], goodLines: ["Click a message", "Reading pane opens beside the list", "List stays put, scroll preserved", "Archive and keep scanning", "Open full page only to focus and reply"], badCaption: "Triaging 40 emails via full-page loads resets scroll and context on every open, so the user keeps losing their place.", goodCaption: "The drawer is reversible inspection: glance, decide, close, keep scanning, with the full view reserved for the reply that needs real estate." },
  "dashboards-entry-points-pat-4": { archetype: 'toggle-fix', subject: "Linear new workspace", badLabel: "Blank first run", goodLabel: "Seeded demo state", badLines: ["Empty board, zero issues", "No columns to react to", "'Now what?' at the make-or-break moment", "user invents a task just to see it work", "many close the tab"], goodLines: ["Sample project with real-looking issues", "Board looks alive: Todo / In Progress / Done", "'Sample data - clear anytime' label", "One obvious first action: New issue", "product shown working before you build"], badCaption: "A blank board on first login says 'now what?' at the exact moment 40-60% of trials decide it isn't worth it.", goodCaption: "Clearly-labeled seeded issues show the product working, then invite the user to clear them and start real work with one action." },
  "dashboards-entry-points-pat-5": { archetype: 'toggle-fix', subject: "Grafana dashboard link", badLabel: "State in component memory", goodLabel: "URL-encoded, shareable view", badLines: ["/d/abc123", "time range + template vars in local state", "paste link to teammate", "they land on the default dashboard", "'which window were you looking at?'"], goodLines: ["/d/abc123?from=now-1h&var-service=checkout", "time range and filters live in the URL", "paste link to teammate", "identical window and filters reconstruct", "named saved views with clean permalinks"], badCaption: "If view state lives only in component memory, a shared incident link opens the default dashboard and the teammate sees a different window.", goodCaption: "Encode time range, filters, and selection in the URL, so a pasted link lands everyone on the exact same view during an incident." },
  "dashboards-entry-points-pat-6": { archetype: 'toggle-fix', subject: "Claude Code permissions", badLabel: "Confirm everything", goodLabel: "Risk-classified gate", badLines: ["Read file  -> confirm?", "List directory -> confirm?", "Run tests -> confirm?", "rm -rf build/ -> confirm?", "by prompt 20 you rubber-stamp all of them"], goodLines: ["Read file: runs, no prompt (low)", "List directory: runs, no prompt (low)", "Edit file: inline approval (medium)", "rm -rf build/: gated, shows exactly what deletes (high)", "the one that matters actually stops you"], badCaption: "Anthropic measured a 93% blanket approval rate when everything prompts, so the one destructive action gets waved through with the rest.", goodCaption: "Auto-run the reversible low-risk actions and reserve the consequence-disclosing gate for the irreversible ones, keeping the prompt meaningful." },
  "dashboards-entry-points-anti-0": { archetype: 'toggle-fix', subject: "Google Analytics 4 default report", badLabel: "Dumping ground", goodLabel: "One question, weighted", badLines: ["Users, Sessions, Engaged sessions, Events...", "30 metric + dimension cards, equal weight", "every chart added because the data exists", "no cue which one is the answer", "users build custom reports or churn"], goodLines: ["Traffic vs 7-day baseline: +2%, healthy", "one hero tile answers the question", "3 supporting cards demoted below", "the rest one click away, not on load", "primary question is obvious"], badCaption: "Every equal-weight chart signals it matters, so the user can't infer the primary question and the screen answers nothing despite holding all the data.", goodCaption: "Promote the one tile that answers 'is my traffic healthy today' and demote the rest, giving the screen a readable gradient." },
  "dashboards-entry-points-anti-1": { archetype: 'toggle-fix', subject: "Jira project board header", badLabel: "Five equal buttons", goodLabel: "One primary, rest demoted", badLines: ["Create   Filters   Group by   Insights   Share", "all styled at similar weight", "no gradient, no 'start here'", "user reads the chrome, not the work", "attention burned choosing"], goodLines: ["[ Create ] filled, prominent", "Filters, Group by, Insights: quiet text buttons", "Share tucked in an overflow menu", "eye lands on the one intended action", "user starts the task immediately"], badCaption: "Five similarly-weighted buttons give no gradient, so the user spends attention navigating the chrome instead of doing the work.", goodCaption: "One promoted primary action gives the entry point a clear starting gradient; the secondary tools recede." },
  "dashboards-entry-points-anti-2": { archetype: 'sequence', badSequence: ["Global nav '+ New' -> Lead form A", "List-view New button -> Lead form B", "Related-list quick action -> mini form C", "each form has subtly different fields", "analytics for 'lead created' split 4 ways"], goodSequence: ["One canonical 'New Lead' entry", "Same form every time", "Muscle memory holds across days", "Reps trust they did it 'right'", "One clean funnel to measure"], badCaption: "Four doors to lead creation with subtly different forms fragment analytics and muscle memory, so reps lose trust in whether they did it right.", goodCaption: "One canonical entry with one consistent form keeps muscle memory intact and analytics attributable." },
  "dashboards-entry-points-anti-3": { archetype: 'toggle-fix', subject: "AWS Console navigation", badLabel: "Schema / org-chart IA", goodLabel: "User-goal IA", badLines: ["EC2   S3   IAM   Lambda   CloudFront   Route 53", "200+ services named after internal teams", "must know 'host a website' = S3 + CloudFront + Route 53", "newcomer has no entry point", "learn Amazon's structure first"], goodLines: ["Host a website", "Store and serve files", "Manage sign-ins", "Set up a domain", "labels match what the user wants to accomplish"], badCaption: "Nav mirrors AWS's org, so a newcomer must already know 'host a website' maps to S3 plus CloudFront plus Route 53 before they can begin.", goodCaption: "Label features by user goal, not by internal service name, so first-click success no longer requires learning the company's structure." },
  "dashboards-entry-points-anti-4": { archetype: 'toggle-fix', subject: "AWS CloudWatch alarm feed", badLabel: "Uniform-urgency badges", goodLabel: "Severity-ranked cards", badLines: ["ALARM  CPUUtilization > 80%", "ALARM  DiskQueueDepth > 5", "ALARM  HealthyHostCount < 1", "all same weight, metric name + threshold only", "open each to learn if it matters"], goodLines: ["SEV-1  HealthyHostCount < 1", "  Impact: checkout down, 100% of users", "  Next: scale-up ASG checkout-web", "SEV-3  CPUUtilization > 80% (info)", "real incident stands out from the noise"], badCaption: "Uniform alarms with only a metric and threshold force on-call to open each one to learn whether it matters, so real incidents hide among noise.", goodCaption: "Rank by severity and attach cause, impact, and next step, so the alert delivers a decision instead of a raw signal." },
  "dashboards-entry-points-anti-5": { archetype: 'toggle-fix', subject: "Airtable new base", badLabel: "Blank empty state", goodLabel: "Designed empty state", badLines: ["Empty grid, no rows", "column headers Field 1, Field 2, Field 3", "no guidance on what to build", "skeleton of the product, zero value", "first-timer has nothing to react to"], goodLines: ["Headline: 'Track anything, your way'", "[ Start from this example ]  primary", "sample rows preview the payoff", "one clear first action", "value shown before any data exists"], badCaption: "A zero-data canvas shows the product's skeleton before any value, maximizing the 'what is this, what do I do' gulf right when trust is decided.", goodCaption: "A designed empty state with a benefit headline, one primary action, and an optional sample shows value before the user has built anything." },
  "dashboards-entry-points-anti-6": { archetype: 'toggle-fix', subject: "Datadog team dashboard", badLabel: "Fully drag-and-drop", goodLabel: "Fixed spine, editable periphery", badLines: ["Every team arranges widgets freely", "'look at the error panel top-left'", "recipient's board looks nothing like yours", "no shared reference points", "positional directions mean nothing"], goodLines: ["Core panels locked in a shared spine", "error panel is top-left for everyone", "periphery still customizable per team", "'the card top-right' survives", "cross-team incident response works"], badCaption: "Full drag-and-drop customization destroys cross-user consistency, so 'look at the error panel top-left' means nothing when everyone's board differs.", goodCaption: "A fixed shared spine with an editable periphery keeps positional directions reliable while still letting teams tune the edges." },
  "dashboards-entry-points-anti-7": { archetype: 'sequence', badSequence: ["Build segments + a 90-day range (10 min)", "state held in component state only", "accidental refresh", "config resets to default", "no way to share the exact view"], goodSequence: ["Build the same report", "filters and range write to the URL", "refresh: view survives", "copy link, send to a colleague", "they open the identical report"], badCaption: "Filters and range that live only in component state mean a refresh wipes ten minutes of setup and there's no way to send the exact view.", goodCaption: "Back the view with the URL so refresh, back, and share all reconstruct the exact report instead of resetting." },
  "dashboards-entry-points-inv-0": { archetype: 'sequence', badSequence: ["Set filters + row selection (component state)", "looks perfect all session", "user refreshes to clear a glitch", "returns to the unfiltered default", "no explanation, place lost"], goodSequence: ["Set filters + selection", "state syncs to the URL query", "refresh", "filters and selection restore", "back button and copy-link work too"], badCaption: "Filters and selection trapped in component-local state look stable through the whole build, then vanish the first time a real user refreshes.", goodCaption: "Sync filters, tab, range, and selection to the URL so refresh, back, and share all survive." },
  "dashboards-entry-points-inv-1": { archetype: 'toggle-fix', subject: "Amplitude chart", badLabel: "Same component for both", goodLabel: "Distinct loading vs empty", badLines: ["Query runs for 6 seconds", "shows the empty-state illustration", "'No data for this event'", "analyst concludes it was never tracked", "stops using the event"], goodLines: ["Query runs: skeleton shimmer first", "then either data renders", "or a distinct 'No events in range' state", "loading and empty look different", "analyst waits instead of misjudging"], badCaption: "A slow query rendering the same 'no data' view as a genuinely empty result makes analysts conclude an event was never tracked and abandon it.", goodCaption: "Show a skeleton while pending, then either data or a distinct empty state, so 'wait' and 'nothing here' never look alike." },
  "dashboards-entry-points-inv-2": { archetype: 'toggle-fix', subject: "Jira create dialog", badLabel: "Both styled primary", goodLabel: "Exactly one primary", badLines: ["[ Create ]   [ Create another ]", "both filled primary variant", "emphasis depends on render order", "eye lands by position habit, not intent", "meaning of 'primary' erodes"], goodLines: ["[ Create ]  filled primary", "Create another  quiet secondary", "one clear visual anchor", "flow's intended action wins the eye", "'primary' means one thing"], badCaption: "Two buttons sharing the same primary variant make emphasis an accident of render order, so behavior drifts and 'primary' loses meaning.", goodCaption: "Exactly one primary variant makes visual primacy an IA decision again: one anchor, matching the flow's intent." },
  "dashboards-entry-points-inv-3": { archetype: 'sequence', badSequence: ["Main nav -> /settings/integrations", "Home card -> /settings/integrations", "Contextual banner -> /settings/integrations", "3 analytics events, same page", "funnel split, support can't give one instruction"], goodSequence: ["One documented path to settings", "single analytics event", "support gives one reliable instruction", "muscle memory consolidates", "clean attribution"], badCaption: "A nav link, a home card, and a banner all routing to the same page fragment analytics and muscle memory, so support can't give one reliable instruction.", goodCaption: "Consolidate to one canonical route (or attribute the source cleanly) so the funnel and the instructions stay coherent." },
  "dashboards-entry-points-inv-4": { archetype: 'sequence', badSequence: ["Swap 2 ETH -> USDC, click", "UI shows 'Swap complete', balance updated", "on-chain tx reverts", "error toast fires and auto-dismisses", "user acts on a balance that never changed"], goodSequence: ["Swap 2 ETH -> USDC, click", "UI shows 'Pending' until on-chain confirm", "tx reverts", "balance rolls back visibly", "persistent error + Retry, no ghost balance"], badCaption: "The UI keeps the optimistic 'complete' and the error toast vanishes before the user sees it, so they trust a balance that never changed, indistinguishable from theft in crypto.", goodCaption: "Hold the pending state until on-chain confirmation, then roll the value back visibly with a persistent error and retry." },
  "dashboards-entry-points-inv-5": { archetype: 'reveal', subject: "Firebase admin panel", opaqueLabel: "Billing panel hidden for this role  (screen looks gated)", revealedLines: ["Network tab: GET /users/me/billing -> 200", "Firestore rule allows the doc read", "full billing payload in the response body", "role check ran in the browser only", "non-admin reads it in devtools"], badCaption: "Hiding a module with a client-side role check while Firestore still returns the data means the gating is zero actual protection: open devtools and read it.", goodCaption: "Enforce the role on the server (Firestore rules) so the sensitive payload is never sent to a browser that shouldn't have it." },
  "dashboards-entry-points-inv-6": { archetype: 'toggle-fix', subject: "Coinbase portfolio", badLabel: "Independent poll intervals", goodLabel: "Shared snapshot", badLines: ["Total tile refreshes every 5s", "Per-asset rows refresh every 8s", "for a beat, rows sum != displayed total", "user can't tell lag from an error", "corrosive in a money product"], goodLines: ["Total and rows read one shared snapshot", "both update together", "sum of rows always equals total", "no transient disagreement", "trust holds"], badCaption: "A total tile and per-asset rows on separate timers disagree for a few seconds after an update, and the user can't tell display lag from a real accounting error.", goodCaption: "Drive related tiles from one shared snapshot so the parts and the whole always agree on screen." },
  "dashboards-entry-points-inv-7": { archetype: 'sequence', badSequence: ["Send link to a filtered database view", "recipient opens it (fresh session)", "default-workspace redirect fires first", "deep link resolves too late", "recipient dead-ends at their own home"], goodSequence: ["Recipient opens the shared link", "auth guard resolves, holds the intended route", "no premature default redirect", "deep link wins", "lands on the exact filtered view"], badCaption: "A default-workspace redirect firing before the deep link resolves bounces the recipient to their home; the sender never reproduces it because they're already in context.", goodCaption: "Order the guards so the deep link resolves before any default redirect, so the shared view always wins." },
  "task-based-saas-mm-0": { archetype: 'toggle-fix', subject: "Linear - new issue", badLabel: "Screen mode", goodLabel: "Loop mode", badLines: ["Issue created", "\"ENG-241 filed successfully\"", "[ Done ]", "(lands on a static confirmation page)"], goodLines: ["ENG-241 - In Progress - you", "Assignee set, added to Current sprint", "Press C to create the next issue", "(result view is the next intent)"], badCaption: "A screen-first tool drops you on a static success page and makes you re-find your place, so the loop never re-opens.", goodCaption: "Submit re-reads state and offers the next intent in one motion, so you file five issues before you think about it." },
  "task-based-saas-mm-1": { archetype: 'toggle-fix', subject: "Cursor - first run", badLabel: "Features-first tour", goodLabel: "Make progress now", badLines: ["Welcome to Cursor", "Step 1 of 6: Configure your model", "Step 2 of 6: Keybindings tour", "\"You're all set!\" (blank editor)"], goodLines: ["Type: \"add pagination to this list\"", "...working code appears in your file", "12 lines written in 3s", "\"I just did that faster than I could alone\""], badCaption: "Opening on a model-config panel and a keybindings tour buries the one moment that makes people switch editors.", goodCaption: "Leading straight to real working code delivers the felt win. People hire progress they can feel, not your settings screen." },
  "task-based-saas-mm-2": { archetype: 'toggle-fix', subject: "Coinbase - first action", badLabel: "Seed phrase first", goodLabel: "Custodial first, defer custody", badLines: ["Step 1: Write down your 12-word seed phrase", "\"Never share this. Lose it and funds are gone forever.\"", "[ I have written it down ]", "(max anxiety, irreversible, on step one)"], goodLines: ["Sign in with email", "You're in - buy your first $10 of BTC", "Custody decision deferred until later", "(anxiety low enough to start the loop)"], badCaption: "The seed phrase is crypto's highest-anxiety first action; front-loading it kills the loop before it ever starts.", goodCaption: "Deferring the scary custody step until after felt value is how Coinbase onboarded millions who would have bounced." },
  "task-based-saas-mm-3": { archetype: 'slider-map', sliderLabel: "Candidate activation event", outputLabel: "Retention curve separation", badCaption: "Optimizing \"workspace created\" celebrates a number that has nothing to do with the habit holding.", goodCaption: "Activation is the earliest event that actually splits survivors from churners: a team sending 2,000 messages, found by staring at cohorts." },
  "task-based-saas-mm-4": { archetype: 'meter', headline: "First value in under 1 minute", breakdown: [{ label: "Deploy from template or Git repo", value: 45 }, { label: "Account details (deferred)", value: 0 }, { label: "Domain settings (deferred)", value: 0 }, { label: "Competitor: DNS + env vars + build config first", value: 600 }], badCaption: "Requiring DNS setup, environment variables, and a build config before the first deploy burns the entire patience budget before the aha.", goodCaption: "Vercel's wedge is time-to-first-deploy: a live URL arrives before you've spent your patience, and everything else defers." },
  "task-based-saas-mm-5": { archetype: 'before-after', subject: "Notion - the block model", badLabel: "Flow-first", goodLabel: "Noun-first (the block)", badLines: ["\"Write a doc\" - its own feature", "\"Build a table\" - a separate feature", "Doc text and table rows behave differently", "System fractures as verbs are added"], goodLines: ["One noun: the block", "Relationships: nesting, references, databases", "Verbs hang off it: drag, embed, turn-into, link", "A page and a database row behave consistently"], badCaption: "A flow-first competitor designs \"write a doc\" and \"build a table\" as separate features and the system fractures.", goodCaption: "Define the object graph first and Notion can add verbs for years without the system breaking. Nouns before verbs." },
  "task-based-saas-mm-6": { archetype: 'before-after', subject: "GitHub - action friction", badLabel: "Uniform friction", goodLabel: "Calibrated to reversibility", badLines: ["Star repo -> type \"owner/repo\" to confirm", "Delete repo -> type \"owner/repo\" to confirm", "Same weight on trivial and catastrophic", "Nobody stars anything; muscle memory nukes repos"], goodLines: ["Star repo -> one click, undo with a click", "Delete repo -> type the full repo name", "Friction scales with blast radius", "You treat the destructive one seriously"], badCaption: "If deleting a repo were as easy as starring, people nuke repos by muscle memory; if starring cost as much, nobody stars.", goodCaption: "GitHub matches confirmation cost to reversibility, so the friction lands exactly where the stakes are." },
  "task-based-saas-pat-0": { archetype: 'before-after', subject: "Duolingo - first session", badLabel: "Full dashboard", goodLabel: "Straight-line with bumpers", badLines: ["Home: Leagues, Friends, Streaks, Shop, Profile", "Settings and social features up front", "Where do I start?", "User wanders off before any lesson"], goodLines: ["Pick a language", "Take a quick placement", "Complete one lesson", "Bail mid-lesson -> notification pulls you back"], badCaption: "Any feature shown up front is a gutter the first-timer falls into before reaching the one job.", goodCaption: "One line to \"complete a lesson and feel you learned\": leagues, friends, and streaks stay hidden until after that first win." },
  "task-based-saas-pat-1": { archetype: 'before-after', subject: "Todoist - new project", badLabel: "Bare placeholder", goodLabel: "Teaching empty state", badLines: ["No tasks yet", "(centered gray text)", "", "User supplies the imagination and the effort"], goodLines: ["Buy groceries  o  today", "Draft launch email  o  tomorrow", "[ Quick-add task ] (already focused)", "\"This is how the project feels once populated\""], badCaption: "A bare \"no tasks yet\" makes the user supply the imagination and the effort at the moment they decide if the tool is worth learning.", goodCaption: "Ghost example tasks, a focused quick-add bar, and a one-line pitch teach the loop instead of apologizing for the blank." },
  "task-based-saas-pat-2": { archetype: 'before-after', subject: "Figma - first file", badLabel: "Setup first", goodLabel: "Do-it-for-me first turn", badLines: ["Create a project", "Define a grid", "Set up a library", "Invite your team - then you may design"], goodLines: ["Open a file", "Canvas is pre-loaded enough to touch", "Drag, resize, edit a shape in seconds", "First real interaction before any setup"], badCaption: "Front-loading project, grid, and library setup burns the first felt moment before the user touches the canvas.", goodCaption: "Figma lets you manipulate design objects the instant you sign up and defers every setup step. Fake it or defer it." },
  "task-based-saas-pat-3": { archetype: 'sequence', badSequence: ["Agent writes edits to 6 files on disk", "Runs the change", "Shows you a diff after the fact", "Damage already on disk - revert manually"], goodSequence: ["Agent lays out the intended edits as a plan", "You read the steps as an artifact", "Edit or redirect a step before it runs", "Approve -> agent writes to disk"], badCaption: "Executing first and showing a diff after means the damage is already on disk for a high-blast-radius change.", goodCaption: "Showing the plan as an editable artifact first turns the agent from a thing that happened to you into one you steer." },
  "task-based-saas-pat-4": { archetype: 'meter', headline: "Activated: account created", breakdown: [{ label: "Setup: onboarding call + inbox import", value: 40 }, { label: "Aha: cleared inbox with keyboard shortcuts", value: 35 }, { label: "Habit: reached for shortcuts reflexively days later", value: 25 }, { label: "\"Account created\" alone predicts retention", value: 0 }], badCaption: "Measuring only \"account created\" celebrates a number that doesn't hold the retention curve.", goodCaption: "Superhuman instruments Setup, Aha, and Habit as three separate loops and coaches each, because one event isn't enough." },
  "task-based-saas-pat-5": { archetype: 'toggle-fix', subject: "Stripe - payment link created", badLabel: "Terminal success", goodLabel: "State + next action", badLines: ["Payment link created", "\"Nice work!\"", "[ Back to dashboard ]", "(bounce to a blank home to figure out what's next)"], goodLines: ["https://buy.stripe.com/live/abc123  [ Copy ]", "Live and ready to share", "[ Share ]  [ Create another ]  [ View payments ]", "Next likely job is right there"], badCaption: "A terminal \"success\" with no onward path dumps merchants on a blank dashboard to figure out what's next.", goodCaption: "Stripe pairs the read-back link with the highest-probability next job, so merchants stay in a productive loop." },
  "task-based-saas-anti-0": { archetype: 'before-after', subject: "Jira - \"what is my team doing this week?\"", badLabel: "Feature-shaped nav", goodLabel: "Job-shaped nav", badLines: ["Boards | Backlogs | Filters | Reports | Admin", "The job is split across five areas", "Each named after a Jira concept", "New user concludes the tool can't do it"], goodLines: ["This week", "My team's work", "What's blocked", "One place answers the actual question"], badCaption: "Menus named after internal modules force users to reverse-engineer which feature performs their job, spread across four tabs.", goodCaption: "Labeling nav by user jobs puts \"what is my team doing this week\" in one place instead of fragmenting it across Jira concepts." },
  "task-based-saas-anti-1": { archetype: 'toggle-fix', subject: "MetaMask - send transaction", badLabel: "Fire-and-forget", goodLabel: "Loop closes", badLines: ["Sending...", "(brief pending spinner)", "Balance: 1.204 ETH", "Did it go through? Open a block explorer to find out"], goodLines: ["Sent - 0.5 ETH to 0x8f...c21a", "Confirmed on-chain - block 21,004,882", "Balance: 0.704 ETH (updated)", "[ View receipt ]"], badCaption: "Broadcasting a tx and never surfacing its finalized state is the classic loop that never closes - the user cannot tell if their money moved.", goodCaption: "A persistent read-back of the finalized state closes the loop, so \"did it work?\" is answerable in the UI itself." },
  "task-based-saas-anti-2": { archetype: 'before-after', subject: "B2B SaaS - onboarding", badLabel: "Feature carousel", goodLabel: "One guided first action", badLines: ["Coach-mark: here's the sidebar", "Coach-mark: here's the settings gear", "Coach-mark: search, notifications, help", "\"You're all set!\" -> blank workspace, nothing made"], goodLines: ["Let's create your first report together", "You pick the data, we render the chart", "Report saved - it's real and yours", "You remember how to do it again"], badCaption: "Narrated overlays produce nothing; \"onboarding completion\" hits 80% while week-2 retention stays flat because narration isn't progress.", goodCaption: "A single guided first action produces a real artifact the user can reproduce, which is what actually predicts retention." },
  "task-based-saas-anti-4": { archetype: 'before-after', subject: "AWS Console - destructive actions", badLabel: "Uniform confirm", goodLabel: "Calibrated gate", badLines: ["Save settings -> \"Are you sure? [Confirm]\"", "Resend email -> \"Are you sure? [Confirm]\"", "Terminate instance -> \"Are you sure? [Confirm]\"", "Same modal trains click-through on everything"], goodLines: ["Save settings -> one click", "Resend email -> one click", "Terminate instance -> type \"i-04a2f...\"", "Delete S3 bucket -> type the bucket name"], badCaption: "When deleting a production bucket feels the same as any other confirm, people delete production buckets by reflex.", goodCaption: "AWS moved high-blast-radius actions to type-to-confirm, a qualitatively different gate from a routine save." },
  "task-based-saas-anti-5": { archetype: 'sequence', badSequence: ["Session 1: \"Be concise, I'm a Python dev\"", "Honored for this conversation only", "New session: preferences forgotten", "Re-brief the same context every single time"], goodSequence: ["Session 1: \"Be concise, I'm a Python dev\"", "Correction persisted to memory", "New session: opens concise, assumes Python", "Value compounds - no re-briefing tax"], badCaption: "Re-briefing tax is why early conversational agents felt like a toy: corrections that don't internalize make the product feel broken.", goodCaption: "The value of an agent compounds only if corrections stick; persistent memory ends the re-brief on every session." },
  "task-based-saas-anti-6": { archetype: 'before-after', subject: "Early SaaS MVP - reports", badLabel: "Flow-first (three flows)", goodLabel: "Noun-first (one object)", badLines: ["\"Create a report\" - its own screens + report shape", "\"Share a report\" - a subtly different report", "\"Schedule a report\" - a third report shape", "No single place to see all your reports; nav grows per flow"], goodLines: ["Report: one canonical object with a home", "All reports live in one place", "Verbs hang off it: create, share, schedule", "A fourth verb slots in without a new top-level tab"], badCaption: "Three separately-designed report flows yield three subtly different report objects and a nav that grows an item per flow.", goodCaption: "Define \"report\" as one canonical noun with a home, then attach verbs; the foundation absorbs the next task cleanly." },
  "task-based-saas-inv-0": { archetype: 'sequence', badSequence: ["Agent writes new value to the record", "POST 200 OK", "Success handler fires a \"Done\" toast", "On-screen object still shows the OLD values"], goodSequence: ["Agent writes new value to the record", "POST 200 OK", "Handler refetches the mutated object", "On-screen object re-renders with the new values"], badCaption: "The write succeeds but the evaluation half of the loop is missing: nothing refetches, so the user stares at stale data that contradicts the toast.", goodCaption: "Re-reading and re-rendering the mutated object closes the loop, so the confirmation and the screen finally agree." },
  "task-based-saas-inv-1": { archetype: 'sequence', badSequence: ["Confirm swap -> UI shows new balance instantly", "On-chain tx reverts (slippage / gas)", "onError is empty - nothing runs", "UI keeps showing tokens you never received"], goodSequence: ["Confirm swap -> UI shows new balance optimistically", "On-chain tx reverts (slippage / gas)", "onError rolls the balance back", "\"Swap failed: slippage exceeded\" surfaced"], badCaption: "Optimistic UI with an empty onError shows a balance that never changed on-chain; in crypto that is indistinguishable from being robbed.", goodCaption: "A real rollback plus a visible revert reason keeps the UI honest, so users don't make decisions on a fiction." },
  "task-based-saas-inv-2": { archetype: 'slider-map', sliderLabel: "Where the activation event fires", outputLabel: "Correlation with week-4 retention", badCaption: "Firing activation on welcome-modal dismissal reports 85% and climbing while retention decays, because dismissing a modal produces no value.", goodCaption: "Point the event at a value-producing action and the reported rate finally tracks the retention it is supposed to predict." },
  "task-based-saas-inv-4": { archetype: 'meter', headline: "First value gated behind a data connection", breakdown: [{ label: "Connect data warehouse (IT-gated, multi-step)", value: 480 }, { label: "Wait on blocking integration", value: 120 }, { label: "See your first chart", value: 0 }, { label: "Seeded with sample data instead", value: 20 }], badCaption: "A required, synchronous data connection consumes the evaluator's entire time-to-value budget before a single chart renders, so many bounce.", goodCaption: "Seeding sample data and deferring the connection lets a solo evaluator see an insight in seconds. Tools that win this category defer the integration." },
  "task-based-saas-inv-5": { archetype: 'before-after', subject: "Enterprise console - \"onboard a new employee\"", badLabel: "Routes from module names", goodLabel: "Routes designed from jobs", badLines: ["/users   (users service, team A)", "/roles   (roles service, team B)", "/policies   (policy service, team C)", "/audit   -> one goal touches four routes"], goodLines: ["/onboard-employee", "Create the account", "Assign the role", "Grant access + record it - one route, one job"], badCaption: "Routes generated from microservice boundaries fragment \"onboard a new employee\" across four module-shaped tabs; renaming nav labels wouldn't fix it.", goodCaption: "Designing the route from the admin's actual job puts the whole task on one path instead of the code's org chart." },
  "task-based-saas-inv-6": { archetype: 'before-after', subject: "Internal ops tool - one Confirm everywhere", badLabel: "Generic Confirm reused", goodLabel: "Friction tied to reversibility", badLines: ["Toggle feature flag -> \"Are you sure? [Confirm]\"", "Resend email -> \"Are you sure? [Confirm]\"", "Delete customer account -> \"Are you sure? [Confirm]\"", "Identical dialog on trivial and irreversible"], goodLines: ["Toggle feature flag -> one click", "Resend email -> one click", "Delete customer account -> type \"acme-corp\"", "Irreversible path carries qualitatively more weight"], badCaption: "One generic Confirm component used everywhere means the destructive path carries the same weight as the trivial one, so operators dismiss it by reflex.", goodCaption: "Reading the code and coloring confirms by reversibility exposes it; the irreversible action must carry more friction than the trivial one." },
  "task-based-saas-inv-7": { archetype: 'reveal', subject: "Autonomous agent - run status", opaqueLabel: "Thinking...", revealedLines: ["1. Read requirements doc (2 sources)", "2. Searched codebase for the auth handler", "3. Drafted the migration", "4. Ran tests - 3 passed, 1 failed", "...14 steps, all already logged server-side"], badCaption: "The agent's tool calls and decisions are logged to backend traces but never rendered, so the user sees only a spinner and can't tell work from an infinite loop.", goodCaption: "Surfacing the action log the backend was already writing lets trust form the instant the hidden steps appear." },
  "task-based-saas-inv-8": { archetype: 'before-after', subject: "PM tool - new workspace", badLabel: "Hard-coded \"No data\"", goodLabel: "Designed zero-state", badLines: ["No projects yet", "(centered gray text, no button)", "", "Hit right after onboarding dumps you here"], goodLines: ["Projects group your work and track progress", "Marketing launch  o  3 tasks (ghost preview)", "[ Create your first project ]", "A first-run user can actually act"], badCaption: "The zero-state is a placeholder string, so first-run users hit a wall the moment the tour ends - a wall the team never sees because their accounts are full of test data.", goodCaption: "A designed empty state with benefit, ghost preview, and one CTA turns the worst moment into the first lesson." },
  "task-based-saas-inv-9": { archetype: 'meter', headline: "Activation up 20% QoQ", breakdown: [{ label: "Week 1 retention", value: 62 }, { label: "Week 2 retention", value: 34 }, { label: "Week 4 retention", value: 15 }, { label: "Week 6 retention (activated cohort)", value: 3 }], badCaption: "Activation and retention live on separate dashboards, so a 20%-up activation number hides a cohort curve decaying to near-zero by week 6.", goodCaption: "Overlaying the two, joined by user, reveals the activation event was never a true aha, so raising it moved nothing." },
  "deceptive-patterns-trust-mm-0": { archetype: 'toggle-fix', subject: "Prime membership - Cancel", badLabel: "Iliad flow", goodLabel: "Symmetric flow", badLines: ["Page 1 of 4: Are you sure? You'll lose free delivery", "[ Keep my benefits ]  (big, blue, default)", "Remind me later", "Continue to cancel  (small grey text link)"], goodLines: ["Cancel Prime membership", "[ Cancel membership ]  (primary, same weight as Keep)", "[ Keep Prime ]", "Done in one step. No restated offers."], badCaption: "Asymmetric plus Restrictive plus Information-Hiding stacked: the cancel action is styled weaker than keep-my-benefits at every step across four pages.", goodCaption: "One step, and Cancel carries the same visual weight as Keep. Judge the mechanism, not the label: no asymmetry, no restriction, nothing hidden." },
  "deceptive-patterns-trust-mm-1": { archetype: 'before-after', subject: "Coinbase Wallet - Confirm send", badLabel: "Trust on a generic page", goodLabel: "Trust at the confirm step", badLines: ["Confirm send", "To: 0x9f...c2a1", "Amount: 0.5 ETH", "[ Confirm ]", "(Security info lives on a separate /trust page)"], goodLines: ["Confirm send", "You hold the keys - non-custodial, Coinbase can't move this", "Network fee: 0.0004 ETH (est.)", "To: 0x9f...c2a1  Amount: 0.5 ETH", "[ Confirm ]"], badCaption: "The trust signal is real but off-screen on a generic page, so it is never seen at the moment of the decision.", goodCaption: "Prominence times Interpretation done right: custody framing and network fee sit on the action screen, so the signal is both seen and understood in the terms a crypto user actually weighs." },
  "deceptive-patterns-trust-mm-2": { archetype: 'reveal', subject: "Stripe Dashboard", opaqueLabel: "Trusted by millions of businesses", revealedLines: ["Ability: 99.999% API uptime, published on status.stripe.com", "Integrity: docs match live API behavior, versioned changelog", "Benevolence: full event + audit log, every charge inspectable", "Every claim links to a surface you can check yourself"], badCaption: "A badge wall asks for trust it hasn't shown: the claim is a slogan with nothing inspectable behind it.", goodCaption: "Trustworthiness made inspectable across Ability, Benevolence, and Integrity. Trust tracks the evidence surface, not the badge." },
  "deceptive-patterns-trust-mm-3": { archetype: 'slider-map', sliderLabel: "Real confidence of the suggestion", outputLabel: "Visual weight of the ghost text", badCaption: "Uniform ghost styling flattens confidence: a shaky guess and near-certain boilerplate render identically, so developers accept both at the same rate and overtrust the risky ones.", goodCaption: "Calibrated presentation varies the signal with real confidence, so reliance tracks reliability instead of tone." },
  "deceptive-patterns-trust-mm-4": { archetype: 'sequence', badSequence: ["2018-2023: ship hardware wallet, trust +1 per good year", "Trust meter: high, built linearly over years", "Dec 2023: Ledger Connect Kit compromised (supply-chain)", "Injected drainer signs setApprovalForAll on victims' wallets", "On-chain transfer confirmed - irreversible, funds gone", "Trust meter: drops to zero on one event"], goodSequence: ["Trust accrues one notch per good interaction", "A single irreversible violation flattens all of it", "No later success repairs the cliff-edge collapse"], badCaption: "One irreversible loss event collapsed years of accrued trust, because on-chain transfers cannot be undone. Linear build, cliff-edge collapse.", goodCaption: "Asymmetry of consequences: design for the one event that ends it, because trust breaks far faster than it builds." },
  "deceptive-patterns-trust-mm-5": { archetype: 'sequence', badSequence: ["Subscribe: click Subscribe on nytimes.com", "Enter card, click Confirm - done, 2 clicks", "Cancel: no cancel button in account settings", "Call 1-800 or start a chat, business hours only", "Wait in queue, decline the retention offer", "Agent processes it - many minutes, one route out"], goodSequence: ["Subscribe: 2 clicks on the web", "Cancel: 2 clicks in the same account settings", "Same medium, same effort, no phone call"], badCaption: "No screen looks deceptive. The obstruction lives entirely in the process asymmetry - a two-click subscribe against a phone-only cancel - which is the defining trait of sludge.", goodCaption: "Surface the asymmetry by counting routes and waits across the whole path. The fix: cancel is as light as subscribe." },
  "deceptive-patterns-trust-pat-0": { archetype: 'reveal', subject: "Rabby Wallet - sign transaction", opaqueLabel: "Approve  -  Send 10 USDC to 0xABC", revealedLines: ["Simulated from the calldata itself:", "Send: 10 USDC", "Approval: UNLIMITED USDC allowance to 0xABC", "Balance after: -10 USDC now, drainable later", "Sign the sentence, not the bytes"], badCaption: "Signing bytes: the friendly summary hides an unlimited approval buried in the calldata.", goodCaption: "Reversibility-first: Rabby decodes and pre-simulates before you commit, so consent is informed and the unlimited approval is visible before signing." },
  "deceptive-patterns-trust-pat-1": { archetype: 'sequence', badSequence: ["Roach motel: subscribe in 2 clicks", "Cancel: hunt for a hidden link or a phone number", "Retention wall, downgrade offers, confirm-shaming"], goodSequence: ["Subscribe: 2 clicks in account settings", "Cancel membership: 2 clicks, same settings, no call", "Return anytime - reinstates instantly, no penalty"], badCaption: "When the exit is heavier than the entry, cancellation becomes a resented trust event.", goodCaption: "Symmetric exits: cancel in the same few clicks it took to subscribe. The anti-roach-motel rule turns cancellation into a non-event." },
  "deceptive-patterns-trust-pat-2": { archetype: 'slider-map', sliderLabel: "Real grounding strength of the answer", outputLabel: "Displayed confidence / visual weight", badCaption: "The confidence channel is uniform even when grounding is weak - and roughly a third of cited URLs misattribute the claim - so users over-rely on the confident voice.", goodCaption: "Honest uncertainty surfacing: visual weight and the confidence band move with the real grounding, and the user can check the span, not just the presence of a citation." },
  "deceptive-patterns-trust-pat-3": { archetype: 'reveal', subject: "Etherscan - transaction receipt", opaqueLabel: "Swap complete  [ Success ]", revealedLines: ["Resolved inputs: swap 2 ETH for 3,410 USDC", "Actor: 0x71...9d (your address)", "Contract: verified source, replayable from chain", "Tx hash: 0x4c8f... (tamper-evident, independent of the dapp)"], badCaption: "A success toast asks you to take the interface's word for what happened.", goodCaption: "Provenance and receipts: the exact effects are replayable from the chain itself, so Integrity is inspectable at the moment it matters, not asserted." },
  "deceptive-patterns-trust-pat-4": { archetype: 'before-after', subject: "MetaMask - signature request", badLabel: "Signal in the help center", goodLabel: "Signal at the signing moment", badLines: ["Site: app-uniswap-v3.xyz", "[ Sign ]", "(Phishing guidance lives in support.metamask.io)"], goodLines: ["Warning: app-uniswap-v3.xyz flagged as a known phishing domain", "Network: Ethereum Mainnet", "This request could grant access to your funds", "[ Reject ]   [ Sign anyway ]"], badCaption: "A trust signal in the footer or help center is never read at the hesitation point.", goodCaption: "Just-in-time, framed: the phishing warning and network context hit inline at the signing moment, in the terms the user is deciding on. Noticed and interpreted." },
  "deceptive-patterns-trust-pat-5": { archetype: 'toggle-fix', subject: "OneTrust cookie banner", badLabel: "Asymmetric", goodLabel: "Symmetric", badLines: ["[ Accept All ]  (large, primary)", "Manage preferences  (small link)", "Reject sits one modal deeper", "Simulated accept rate: 22-23 pts higher"], goodLines: ["[ Accept All ]     [ Reject All ]", "Same widget, same depth, same weight", "Manage preferences", "Consent that is actually freely given"], badCaption: "Burying Reject a layer deeper than Accept manufactures consent that isn't freely given - a measurable 22-23 point lift and a direct GDPR problem.", goodCaption: "Neutral defaults and symmetric choice architecture: same widget, same depth for both, removes the manipulation and the legal exposure." },
  "deceptive-patterns-trust-anti-0": { archetype: 'reveal', subject: "Wallet approval prompt", opaqueLabel: "Approve  -  Approve 10 USDC?   [ Approve ]", revealedLines: ["Decoded calldata:", "Function: setApprovalForAll(operator, true)", "Grants: ALL NFTs in your collection to 0xDrainer", "On-chain finality: permanent, no undo", "You would lose the entire collection in one click"], badCaption: "Blind signing: the displayed intent and the signed bytes diverge, and on-chain finality makes the loss permanent.", goodCaption: "Clear-signing: the summary must be derived from the payload, so setApprovalForAll can never hide behind Approve 10 USDC." },
  "deceptive-patterns-trust-anti-1": { archetype: 'toggle-fix', subject: "Email-capture popup", badLabel: "Confirmshaming", goodLabel: "Neutral decline", badLines: ["[ Yes, send me my discount ]", "No, I like paying full price", "Brand-sentiment meter: dropping", "Screenshot shared to socials"], goodLines: ["[ Get my 15% off ]", "No thanks", "Brand-sentiment meter: intact", "Same opt-in, no contempt"], badCaption: "The shaming decline label lifts opt-ins short term and generates contempt long term, because users feel manipulated - regulators now cite it as a textbook covert pattern.", goodCaption: "A neutral No thanks: the decline reads as a real choice, so the brand keeps the opt-in without the sentiment hit." },
  "deceptive-patterns-trust-anti-2": { archetype: 'toggle-fix', subject: "Booking.com - hotel result", badLabel: "Fabricated urgency", goodLabel: "Grounded signal", badLines: ["Only 1 room left on our site!", "37 people are looking right now", "Reload the page: same 1 room, same 37 people", "Not consistently backed by real availability"], goodLines: ["4 rooms left at this price (live inventory)", "No fake viewer counter", "Reload: numbers reflect the real feed", "A savvy user who reloads finds nothing to catch"], badCaption: "When the pressure signal is not grounded in truth, one reload exposes the fabrication and the entire brand's numbers become suspect.", goodCaption: "Ground the scarcity in real inventory or drop it: the signal survives a reload and a second-site check." },
  "deceptive-patterns-trust-anti-3": { archetype: 'slider-map', sliderLabel: "Real correctness of the answer", outputLabel: "Confidence of the prose", badCaption: "Uniform confident tone flattens the difference between a solid answer and a fabricated legal citation, so users act on both - and when the act is a filed brief, the manufactured confidence is what gets sanctioned.", goodCaption: "Let the visual weight track correctness: flag the low-grounding answer instead of narrating a hallucination in the same voice as a fact." },
  "deceptive-patterns-trust-anti-4": { archetype: 'sequence', badSequence: ["Subscribe: pick plan, enter card, Confirm - frictionless", "(Annual-plan early-termination fee not surfaced up front)", "Cancel: dig through account, hit a retention wall", "Chat handoff, offers, are-you-sure prompts", "Surprise early-termination fee revealed at the end", "Exit path ~3x longer than entry"], goodSequence: ["Subscribe: pick plan, see ETF terms plainly, Confirm", "Cancel: one Cancel plan button in the same settings", "Fees shown before you commit, not hidden on exit"], badCaption: "Roach motel: frictionless entry, an obstacle-course exit, with the early-termination fee hidden - a quantifiable asymmetry the DOJ and FTC made legally actionable.", goodCaption: "Make exit as easy as entry and surface fees before commit. Symmetry converts a legal and reputational liability back into an honest flow." },
  "deceptive-patterns-trust-anti-5": { archetype: 'before-after', subject: "IAB TCF consent banner", badLabel: "Asymmetric TCF banner", goodLabel: "Symmetric banner", badLines: ["[ Accept All ]  (prominent, single click)", "More options  ->  Reject sits one modal deeper", "Vendor purposes pre-enabled (toggles on by default)", "Consent that is not freely given"], goodLines: ["[ Accept All ]     [ Reject All ]", "Same depth, one click each", "All vendor purposes off until chosen", "GDPR-valid consent"], badCaption: "Reject behind a second click plus pre-enabled vendor purposes manufactures consent that isn't freely given - a direct GDPR violation with fines attached.", goodCaption: "Reject at the same depth as Accept, purposes off by default: the asymmetry and the legal exposure both disappear." },
  "deceptive-patterns-trust-anti-6": { archetype: 'before-after', subject: "Crypto exchange landing page", badLabel: "Badge theater", goodLabel: "One real badge", badLines: ["As featured in: [logo][logo][logo][logo][logo]", "Audited by [badge]  (links nowhere)", "Listed on [logo][logo][logo][logo][logo]", "Density signals compensation - experts leave"], goodLines: ["Security audit: [ View full report ]  ->  live PDF", "One claim, verifiable at the source", "No press-logo wall", "Expert trust rises as clutter falls"], badCaption: "The badges evidence nothing and the density itself signals compensation to experienced users, who leave. Trust-badge theater spends design effort repelling the sophisticated audience.", goodCaption: "Swap the wall for one badge that links to a live audit report: fewer signals, each one checkable." },
  "deceptive-patterns-trust-inv-0": { archetype: 'sequence', badSequence: ["Join: fill web form, enter card, Submit - done online", "Cancel: no online option", "Write a cancellation letter", "Send it certified mail, or visit your home club in person", "Wait for it to process across a round-trip", "No single screen looks deceptive"], goodSequence: ["Join online: one web form", "Cancel online: one form, same channel", "No certified letter, no in-person visit"], badCaption: "Signup is a web form; cancellation historically required a certified letter or an in-person visit - obstruction by construction that passes every single-screen review.", goodCaption: "Only counting steps across the whole exit path surfaces it. The fix: cancel in the same channel you joined." },
  "deceptive-patterns-trust-inv-1": { archetype: 'reveal', subject: "Shopify store - social proof popup", opaqueLabel: "Someone in Austin, TX just bought this  -  2 min ago", revealedLines: ["Network tab: no /events or /orders request fired", "Name + city pulled from a static template list", "Timer randomized client-side by the Fomo / Sales Pop app", "Rendered UI alone can't reveal the fabrication"], badCaption: "Nothing in the visual UI reveals the fabrication; the popup is generated from a template, not from real orders. Only the absent events request and the vendor script in the waterfall show it.", goodCaption: "Back social proof with a real events request, or don't show it. Provenance is what separates proof from a static list." },
  "deceptive-patterns-trust-inv-2": { archetype: 'reveal', subject: "Quantcast CMP - consent banner", opaqueLabel: "We care about your privacy   [ Accept All ]", revealedLines: ["DOM: Reject All is a text link nested one modal deeper", "Vendor purpose toggles set true after first paint", "On screen the choice looked available and neutral", "Only a markup + state read catches the pre-steering"], badCaption: "On screen the choice looked available; in the DOM, Reject was a click deeper and purposes were pre-steered on. The violation lives entirely below the visual layer.", goodCaption: "Read the markup and post-paint state, not the screenshot: Reject one layer down and a checkbox flipped true are the whole deception." },
  "deceptive-patterns-trust-inv-3": { archetype: 'reveal', subject: "Uniswap-lookalike dapp - confirm", opaqueLabel: "Approve  -  Approve 10 USDC   [ Confirm ]", revealedLines: ["Decoded transaction object:", "approve(spender = 0xAttacker, amount = 2^256-1)", "= UNLIMITED allowance to an attacker-controlled address", "Confirmation screen is identical to the legitimate one", "Divergence exists only in the decoded calldata"], badCaption: "The cloned confirm screen looks identical to a real one; the divergence exists only in the decoded transaction object, so users who don't decode sign away their tokens.", goodCaption: "Decode the calldata beside the summary: Approve 10 USDC resolves to an unlimited allowance the friendly text never showed." },
  "deceptive-patterns-trust-inv-4": { archetype: 'reveal', subject: "Credit risk dashboard - applicant score", opaqueLabel: "Risk score: 742", revealedLines: ["Raw model response: probability 0.63, 95% interval [0.48-0.78]", "UI discarded the interval entirely", "742 is three fake significant figures on a wide range", "The uncertainty that would change the decision is gone"], badCaption: "The model returned a probability with a wide interval; the UI renders a single crisp 742 with no band, so operators act on the point estimate as if it were exact.", goodCaption: "Diff the raw API response against the render: the discarded confidence interval and the false precision light up. Show the band, not a fake-precise number." },
  "deceptive-patterns-trust-inv-5": { archetype: 'sequence', badSequence: ["Click Mint", "Tx submitted to mempool (not yet mined)", "UI flashes: Success! You own the NFT", "On-chain: tx reverts for slippage / low gas", "UI still claims success - no rollback, no error", "User believes they own an asset they don't"], goodSequence: ["Click Mint", "State: Submitted (pending in mempool)", "State: Confirmed only after it is mined", "If it reverts: show Failed with the reason"], badCaption: "The UI flashed Success the moment the transaction was submitted, before it was mined, and showed nothing when it later reverted. The divergence from on-chain reality is permanent and invisible on the happy path.", goodCaption: "Gate Success on the mined confirmation, not submission, and roll back with a reason on revert. Optimistic UI must not lie about irreversible state." },
  "deceptive-patterns-trust-inv-6": { archetype: 'reveal', subject: "Airline booking - cart total", opaqueLabel: "Total: $487.00   [ Continue to payment ]", revealedLines: ["Initial cart state, pre-added before you touched anything:", "+ Trip protection insurance: $39", "+ Preferred seat upgrade: $28", "data_sharing flag: true (defaulted on)", "No visible checkbox ever showed these"], badCaption: "The add-ons live in the initial cart state and render as the neutral default, so the total silently includes them unless the user finds and removes each. No highlighted checkbox to notice.", goodCaption: "Read the state object against the UI: a pre-added insurance line and a defaulted-on data-sharing flag are the only evidence. Default add-ons off and make each an explicit opt-in." },
  "buying-psychology-hesitation-mm-0": { archetype: 'reveal', subject: "MetaMask - Confirm swap", opaqueLabel: "Contract Interaction  0x38ed1739…a1c2f0", revealedLines: ["You send: 0.5 ETH", "You receive: ~1,300 USDC", "Worst case (max slippage): 1,280 USDC", "To contract: 0x7a25…Router", "Net if it goes wrong: -0.52 ETH"], badCaption: "The one screen meant to protect the user shows a hex blob and a 'Contract Interaction' label. It rendered the payload faithfully and transferred zero information, so sophisticated users abandon and naive ones sign blind.", goodCaption: "Decode the calldata into what actually happens, to whom, and the worst case. The unknown becomes known, so the user can weigh a real decision instead of fleeing ambiguity." },
  "buying-psychology-hesitation-mm-1": { archetype: 'slider-map', sliderLabel: "How much the user has invested (streak length)", outputLabel: "Loss-aversion pushback the warning generates", badCaption: "Firing 'Don't lose your 340-day streak!' at a day-2 user with nothing invested treats loss aversion as a fixed 2.25x law. The fear copy lands on an empty stake and reads as noise.", goodCaption: "Loss aversion scales with accumulated stake, not a constant. Let the pushback track what the user actually owns, so the charge fires hard only where there is real streak to lose." },
  "buying-psychology-hesitation-mm-2": { archetype: 'toggle-fix', subject: "Coinbase - Send to external address", badLabel: "One glossy texture throughout", goodLabel: "Texture changes at the point of no return", badLines: ["Send to external address", "0x9f2a…c71b", "Slick one-tap Send button", "No re-read, no seam, highway speed"], goodLines: ["Send to external address", "Re-read this address: 0x9f2a…c71b", "Copy the last 4: type c71b to continue", "Button slows, copy expands, deliberate confirm"], badCaption: "Browsing balances is a fast System-1 flow, and the irreversible external send keeps the same one-tap feel. The brain wanted to shift into verification mode and the UI never gave it the seam, so a wrong-address send goes through at highway speed.", goodCaption: "Change the texture exactly at the irreversible step: slow the button, expand the copy, add a re-read gate. The seam routes the same user from System 1 into System 2 right where it matters." },
  "buying-psychology-hesitation-mm-3": { archetype: 'slider-map', sliderLabel: "Motivation dial (more hype, bigger subtitle)", outputLabel: "How close the user gets to crossing the action line", badCaption: "The team fights drop-off at a 12-field compliance step by cranking a more motivating subtitle. Motivation was already high at the money moment, so the dot barely crosses the line while the real block, ability cost, sits untouched.", goodCaption: "In B=MAP, motivation is the lever you can barely move at the money moment. Shave ability cost instead (split or pre-fill the fields) and the dot sails over the action line instantly." },
  "buying-psychology-hesitation-mm-4": { archetype: 'toggle-fix', subject: "Vercel - Delete dialog", badLabel: "One dialog for every delete", goodLabel: "Friction weighted by reversibility x blast radius", badLines: ["Delete preview deployment? [Cancel] [Delete]", "Delete production project? [Cancel] [Delete]", "Identical dialog, identical weight", "Both get the same reflexive dismissal"], goodLines: ["Delete preview deployment? [Cancel] [Delete]  (reversible, soft ack)", "Delete production project?  (irreversible, high blast)", "Type the project name to confirm: acme-prod", "The catastrophic one is visibly heavier"], badCaption: "Deleting a throwaway preview and deleting a production project use the same confirm dialog, so uniform friction trains the user to click through everything and the one guard that mattered gets dismissed on muscle memory.", goodCaption: "Reversibility and blast radius set how much friction an action deserves. Let the confirmation get heavier as the action moves toward the irreversible-high-blast corner, so the catastrophic step cannot be dismissed on autopilot." },
  "buying-psychology-hesitation-mm-5": { archetype: 'sequence', badSequence: ["Ask a question", "Blank spinner", "…", "Answer appears"], goodSequence: ["Ask a question", "Searching the web…", "Reading 12 sources…", "Comparing findings…", "Answer appears"], badCaption: "A blank spinner for a 4-second run hides the work, so the wait feels dead and the answer feels unearned. The user cannot tell productive work from a frozen pipeline.", goodCaption: "Narrate the real steps as they run. Operational transparency makes the wait feel productive and the answer feel earned, raising trust in the output even at the same speed." },
  "buying-psychology-hesitation-mm-6": { archetype: 'slider-map', sliderLabel: "The model's true reliability on this suggestion", outputLabel: "Confidence the UI actually conveys", badCaption: "Every suggestion is presented with uniform confidence regardless of how sure the model was, so the conveyed signal flatlines while true reliability moves. Users cannot tell a strong suggestion from a shaky one and default to blanket accept or blanket distrust.", goodCaption: "Appropriate reliance means the conveyed confidence tracks the system's actual reliability. Wire the signal to real certainty so user confidence rises and falls with it, keeping the two needles overlapping." },
  "buying-psychology-hesitation-mm-7": { archetype: 'sequence', badSequence: ["Enter SSN", "Enter bank account and routing number", "Ledger deep in the red, nothing paid back yet", "Risk-sensitive user abandons", "(never reaches any value)"], goodSequence: ["Enter email", "Browse live prices, feel the value", "Set up a watchlist", "Now asked for SSN and bank details, ledger positive", "User completes"], badCaption: "Signup asks for SSN and bank details up front, before the user has seen a single price move. The privacy ledger is deep in the red at the exact step where nothing has been paid back, so risk-sensitive users abandon.", goodCaption: "Every field re-runs the benefit-minus-risk math. Order the asks so value is shown before the sensitive ones land, keeping the ledger positive at each step and carrying the user past the scary fields." },
  "buying-psychology-hesitation-pat-0": { archetype: 'reveal', subject: "Rabby Wallet - Approve token", opaqueLabel: "Approve  [friendly label, no amount shown]", revealedLines: ["Spender: 0xSpender…9c4", "Token: USDC", "Amount: UNLIMITED (2^256-1)", "Warning: this approval can move ALL your USDC", "Recommend: cap to this trade only"], badCaption: "A friendly 'Approve' label hides that the underlying grant is unlimited. A 'Contract Interaction' style screen would have waved this drainer approval straight through.", goodCaption: "Decode the payload into spender, amount, and worst case, and flag the unlimited grant in red. What you see is what you sign, so the blind hash becomes a readable decision." },
  "buying-psychology-hesitation-pat-1": { archetype: 'toggle-fix', subject: "Uniswap - Approve token for swap", badLabel: "Infinite approval, buried", goodLabel: "Exact-amount cap on the surface", badLines: ["Approve USDC", "Amount: Unlimited (default)", "Cap hidden in collapsed 'Advanced' panel", "Whole USDC balance at risk if the spender is exploited"], goodLines: ["Approve USDC", "Approve amount: 1,300 USDC (this trade only)", "Editable number, front and center", "Blast radius capped to the trade if the spender is exploited"], badCaption: "The swap silently defaults to infinite approval, cap buried in a collapsed advanced panel. If the spender contract is later exploited, the user's entire token balance is at risk, not just this trade.", goodCaption: "Default the scope to the exact amount for this trade and put the cap on the surface as an editable number. Minimum viable scope means an exploit can only reach what was approved." },
  "buying-psychology-hesitation-pat-2": { archetype: 'toggle-fix', subject: "GitHub - Delete repository", badLabel: "Plain OK button", goodLabel: "Type the exact name to confirm", badLines: ["Delete this repository?", "[Cancel]  [OK]", "Clickable on autopilot", "Wrong repo deleted without a real read"], goodLines: ["Delete this repository?", "Type acme/payments-prod to confirm:", "[ ______________ ]  [Delete]", "Forces a deliberate read of exactly what is being destroyed"], badCaption: "A single 'Are you sure?' button can be clicked through on muscle memory, so an accidental delete of the wrong target slips right past.", goodCaption: "At the irreversible step only, require typing the exact repo name. The System-2 speed bump forces a deliberate read of what is being destroyed and catches the wrong target." },
  "buying-psychology-hesitation-pat-3": { archetype: 'sequence', badSequence: ["Screen 1: Enter SSN", "Screen 1: Enter full financial detail", "Upload government ID", "KYC wall before any value shown", "User abandons"], goodSequence: ["Enter email", "Tell us what you want to do", "Account set up, ready to move money", "Now: verify ID (here is why we need it)", "Full financial detail, justified inline"], badCaption: "A flat form asks for SSN and full financial detail on screen one, a KYC wall before any value. The privacy ledger is underwater at the first ask.", goodCaption: "Order fields by rising sensitivity, justify each scary ask inline, and defer the highest-risk one until the user has invested effort and can see value. The ledger stays positive at each step." },
  "buying-psychology-hesitation-pat-4": { archetype: 'sequence', badSequence: ["Welcome", "Link your bank account", "Fund $500 to get started", "Big commitment asked cold", "New user hesitates and drops"], goodSequence: ["Welcome", "Buy $5 of crypto", "Watch it move in real time", "You have already done this: now link a bank", "Larger funding feels like continuing"], badCaption: "Leading with the big ask (link a bank, fund seriously) cold gives the user nothing to be consistent with, so the high-commitment step stalls.", goodCaption: "Start with a real, low-cost, reversible first yes: buy $5 and watch it move. The big funding ask then feels like continuing a path the user already chose, not starting a new one." },
  "buying-psychology-hesitation-pat-5": { archetype: 'sequence', badSequence: ["Run task", "Thinking… (single spinner)", "…", "Done"], goodSequence: ["Run task", "Read src/auth/session.ts", "Ran tests: 14 passed, 1 failed", "Edited session.ts (expand to see diff)", "Ran tests: 15 passed", "Done"], badCaption: "A single 'thinking' spinner for a slow run hides everything, so the user cannot tell productive work from a stuck loop. That is exactly where trust in a slow agent is lost.", goodCaption: "Stream the real tool calls, files read, and commands run as a legible verb-object-result feed, each expandable to its raw payload. The user can distinguish working from looping." },
  "buying-psychology-hesitation-pat-6": { archetype: 'toggle-fix', subject: "Apple iOS - Location access", badLabel: "Unlimited is the default", goodLabel: "Safe scope pre-selected and anchored", badLines: ["Allow location access?", "( ) Ask Next Time", "( ) While Using", "(x) Always  <- pre-selected", "Most users never change it, so most grant Always"], goodLines: ["Allow location access?", "(x) Ask Next Time  <- pre-selected", "( ) While Using the App", "( ) Always", "Most users never change it, so most stay least-privilege"], badCaption: "If the broadest scope is the default, defaults dominate and the population ends up over-granting, since most users never change what is pre-selected.", goodCaption: "Pre-select and anchor the reversible, minimally-scoped option. Because defaults dominate, the majority ships with least-privilege access without any effort, shrinking blast radius at population scale." },
  "buying-psychology-hesitation-anti-0": { archetype: 'reveal', subject: "Bybit - Multisig signing", opaqueLabel: "Contract Interaction  0x…benign-looking details", revealedLines: ["Real payload: change implementation contract", "New owner: 0xAttacker…", "Effect: full control of the wallet transferred out", "Displayed UI: benign  |  Signed bytes: hostile", "This is the gap that drained the funds"], badCaption: "Signers approved a transaction whose interface showed benign details while the actual payload authorized moving funds to attacker addresses. The confirmation became a rubber stamp on a payload no one could read.", goodCaption: "Decode the payload on the trusted surface so the signed bytes and the displayed intent are the same thing. The hostile intent that the friendly UI hid becomes visible before signing." },
  "buying-psychology-hesitation-anti-1": { archetype: 'toggle-fix', subject: "Revolut - Send transfer", badLabel: "Blanket 'reduce friction' applied everywhere", goodLabel: "Friction weighted by reversibility", badLines: ["Reorder dashboard card: one tap (fine, reversible)", "Send money to a new recipient: one tap (same ease)", "No confirmation on the irreversible payment", "Mistyped recipient goes through instantly"], goodLines: ["Reorder dashboard card: one tap (reversible, no gate)", "Send money to a new recipient: irreversible", "Confirm recipient and amount before it fires", "The wrong transfer gets caught"], badCaption: "A push to streamline strips the confirmation off transfers, so an irreversible payment now fires with the same ease as reordering a card. The conversion metric rises while the only guard on the irreversible path is gone.", goodCaption: "One-tap is right for reversible actions and catastrophic for irreversible ones. Keep the System-2 speed bump exactly on the irreversible path so a wrong transfer is caught before it commits." },
  "buying-psychology-hesitation-anti-2": { archetype: 'reveal', subject: "AI analysis tool - Progress bar", opaqueLabel: "Analyzing across 47 dimensions…  [3s progress bar]", revealedLines: ["Activity log:", "00:00.02  model call returned (instant)", "00:00.02 - 00:03.00  setTimeout(3000) running", "Real work done: none after the first tick", "The bar is theater, not labor"], badCaption: "The app shows 'Analyzing across 47 dimensions' behind a 3-second timed bar while the model call already returned instantly. The fabricated labor inflates perceived rigor and trains over-trust.", goodCaption: "Expose the underlying activity log and the theater collapses: nothing ran after the first tick. Honest transparency drives the bar from real tool-call events, so the wait maps to actual work." },
  "buying-psychology-hesitation-anti-3": { archetype: 'reveal', subject: "Ticketmaster - Checkout", opaqueLabel: "Ticket price: $80.00", revealedLines: ["Face value: $80.00", "+ Service fee: $18.50", "+ Facility fee: $6.00", "+ Processing fee: $5.50", "Total at final step: $110.00"], badCaption: "The $80 ticket becomes $110 only at the final checkout screen once service, facility, and processing fees appear. Late cost reveal is Baymard's number-one abandonment cause at ~48 percent, and the jump at commitment lands as a felt loss.", goodCaption: "Show the all-in price from step one. When the anchored number never moves at commitment, the loss framing never fires and the abandonment it drives disappears." },
  "buying-psychology-hesitation-anti-4": { archetype: 'toggle-fix', subject: "LinkedIn - Contacts import", badLabel: "Pre-checked sharing + shaming decline", goodLabel: "Neutral defaults + plain decline", badLines: ["[x] Import and share my contacts", "[x] Let others discover me by email", "Continue", "No thanks, I don't want to grow my network"], goodLines: ["[ ] Import my contacts", "[ ] Let others discover me by email", "Continue", "No thanks"], badCaption: "Data-sharing pre-checked and the decline path framed to feel like missing out. The manufactured consent lifts a connection metric short term but poisons trust and drew regulatory and legal scrutiny.", goodCaption: "Leave data-sharing unchecked and make declining a plain, unshamed choice. Real consent costs a little short-term opt-in rate and buys the trust the product actually runs on." },
  "buying-psychology-hesitation-anti-5": { archetype: 'toggle-fix', subject: "Booking.com - Room listing", badLabel: "Fabricated scarcity", goodLabel: "Server-authoritative signal", badLines: ["Only 1 room left!", "Booked 3 times in the last hour", "Refresh the page: badge resets, still 'only 1 left'", "Persists regardless of real inventory"], goodLines: ["3 rooms left at this price", "Deal ends in 04:12:07 (fixed deadline)", "Refresh the page: numbers hold", "Backed by real inventory and a real clock"], badCaption: "'Only 1 room left' and 'booked 3 times this hour' persist regardless of actual inventory. Loss aversion is weak for small everyday stakes, so sophisticated travelers read the fabricated scarcity as pressure and discount the site's other claims.", goodCaption: "Show only scarcity that is real and server-authoritative, so a refresh does not reset it. A truthful signal informs the decision instead of manufacturing a fake loss." },
  "buying-psychology-hesitation-anti-6": { archetype: 'toggle-fix', subject: "Plaid - Connect your bank", badLabel: "Motivation-first fix", goodLabel: "Ability-cost cut", badLines: ["Headline: 'Unlock your full financial picture!'", "Bigger, brighter Connect button", "Same confusing multi-step link screen underneath", "Drop-off unchanged"], goodLines: ["Pick your bank (search)", "One clear step at a time, plain-language labels", "Fewer fields, the confusing step decoded", "Completion moves"], badCaption: "Users drop at a confusing multi-step bank-link screen and the team adds a motivating headline and a bigger button. Motivation was already high at the linking step; the block was ability cost, so the hype moves a vanity metric while the leak stays.", goodCaption: "At the money moment, cut ability cost, not add motivation. Fewer fields and a decoded, plain-language step remove the actual friction, which is the only thing that moves completion." },
  "buying-psychology-hesitation-anti-7": { archetype: 'toggle-fix', subject: "Netflix - Catalog browse", badLabel: "Trim the catalog to 'reduce overload'", goodLabel: "Same size, add decision support", badLines: ["Show fewer titles overall", "Arbitrarily cut the library down", "Lost value, still no way to navigate", "'Choice overload' blamed for the drop"], goodLines: ["Keep the full catalog", "Top Picks for You row", "Because you watched … rows", "A recommended pick surfaced up front"], badCaption: "Blaming choice overload and blindly trimming the catalog is lazy: the jam study does not robustly replicate and the meta-analytic effect is near zero. Cutting the library just loses value.", goodCaption: "The working lever is decision support, not fewer options. Rows, 'Top Picks', and 'Because you watched' make a large set navigable, keeping the value and the engagement." },
  "buying-psychology-hesitation-inv-0": { archetype: 'reveal', subject: "Early MetaMask - Signing modal", opaqueLabel: "RPC response  ->  DOM  (no decode node in between)", revealedLines: ["Insert humanization layer:", "decode(calldata) -> { method, spender, amount }", "Approve -> approve(0xSpender, UNLIMITED)", "Same screen, now readable", "The gap was architectural, not copy"], badCaption: "The modal renders the real payload faithfully, so it looks correct, but the render path goes straight from RPC response to DOM with no decode or humanization node. The absence of that step, not bad copy, is what let malicious approvals through.", goodCaption: "Add the missing decode node between the RPC response and the DOM. The same faithful data becomes a readable intent, and the invisible architectural gap closes." },
  "buying-psychology-hesitation-inv-1": { archetype: 'reveal', subject: "DEX frontend - Approve USDC", opaqueLabel: "[ Approve ]  (cheerful microcopy, no amount)", revealedLines: ["Underlying call: approve(router, 2^256-1)", "Allowance granted: UNLIMITED", "A later exploit of the router drains ALL your USDC", "Not just this trade's worth", "Fix: approve the exact trade amount"], badCaption: "The button says 'Approve' but the call is approve(spender, 2^256-1), an unbounded permission. The friendly label hid the unlimited scope, so users granted far more than they realized.", goodCaption: "Expand the calldata to reveal the 2^256-1 grant, and default the approval to the exact trade amount. The unbounded scope becomes visible and the blast radius shrinks to one trade." },
  "buying-psychology-hesitation-inv-2": { archetype: 'sequence', badSequence: ["JS validates recipient 0xGOOD…", "UI displays 0xGOOD… to the user", "Injected script swaps recipient to 0xEVIL…", "User signs the mutated payload", "Funds go to an address the user never saw"], goodSequence: ["Display and signature read from one source", "Recipient bound to the signed bytes: 0xGOOD…", "Any post-display mutation invalidates the signature", "What is shown is what is signed", "Funds go where the user saw"], badCaption: "Address and amount checks live only in JavaScript, so what the user sees and what gets signed can diverge. An injected script swaps the recipient after the UI validated and displayed the intended address, and the WYSIWYS guarantee breaks silently.", goodCaption: "Bind the displayed values to the signed bytes from one source, so display and signature cannot desync. Any post-display mutation invalidates the signature instead of sending funds elsewhere." },
  "buying-psychology-hesitation-inv-3": { archetype: 'sequence', badSequence: ["Tap Send", "Broadcast transaction", "Flip UI to green 'Sent!' immediately", "Tx is dropped / reverted on-chain", "UI still reads 'Sent!' - false certainty"], goodSequence: ["Tap Send", "Submitted (broadcast)", "Pending (in mempool, not final)", "Confirmed (mined and final)", "Success fires only on real settlement"], badCaption: "The code fires the success state on broadcast, not on settlement. A dropped or reverted transaction still reads as 'Sent!', manufacturing false certainty and hiding the genuinely uncertain pending state, which is indistinguishable from theft.", goodCaption: "Gate success on settlement, not on send. Show submitted, then pending, then confirmed, so the success state means the money actually moved and the uncertain window is honestly displayed." },
  "buying-psychology-hesitation-inv-4": { archetype: 'sequence', badSequence: ["Render token amount: 1,300 USDC (tick 1)", "User anchors on that number", "Gas + price impact resolve from a separate quote (tick 2)", "Total jumps to 1,271 USDC at confirm", "'Number jumped' right at commitment"], goodSequence: ["Compute base + gas + price impact in one path", "Render one all-in figure: 1,271 USDC", "User anchors on the real total", "Nothing moves at confirm", "Anchor holds"], badCaption: "The token amount displays instantly while gas and price impact resolve from a separate quote on a later tick, so the total shifts right before confirm. This reproduces drip-pricing distrust even with honest intent, because the anchor was set on a number that later moved.", goodCaption: "Compute the fee in the same path as the base price and render one all-in figure. The anchor is set on the real total, so nothing jumps at commitment." },
  "buying-psychology-hesitation-inv-5": { archetype: 'slider-map', sliderLabel: "The model's real uncertainty on this suggestion", outputLabel: "What the confidence badge displays", badCaption: "A fixed 'high confidence' badge is not wired to any real signal, so every suggestion looks equally sure while true uncertainty moves underneath. The badge inflates reliance past reliability, and users defer to shaky outputs as readily as strong ones.", goodCaption: "Drive the badge from live logprobs and a verification pass so it tracks real uncertainty. When the answer is shaky the badge visibly drops, and reliance calibrates to reliability." },
  "buying-psychology-hesitation-inv-6": { archetype: 'reveal', subject: "OAuth consent screen", opaqueLabel: "Clean consent screen  [ Authorize ]", revealedLines: ["Initial state object:", "consent = true  (pre-checked)", "scope = 'all'  (broadest set pre-selected)", "share_data = on", "Default authorization exceeds what the user would choose"], badCaption: "The screen looks clean, but broad default scopes and a data-sharing toggle are pre-set to on in state before the user consciously consents. Because defaults dominate and the pre-set scope is barely visible, most users authorize more than intended.", goodCaption: "Inspect the initial state and the over-broad grant is exposed. Default scopes to the minimum and toggles to off, so the pre-set no longer exceeds what the user would have chosen." },
  "buying-psychology-hesitation-inv-7": { archetype: 'toggle-fix', subject: "On-chain transaction UI - Pending tx", badLabel: "Only success and generic-error handled", goodLabel: "Real pending and error states with recovery", badLines: ["Tx stuck pending for minutes", "Endless spinner, no status", "No explanation, no speed-up, no cancel", "User frozen in maximum anxiety"], goodLines: ["Pending: in mempool for 3m, low gas", "Why it is stuck: base fee rose above your bid", "[ Speed up ]  [ Cancel ]", "Timeout edge shows a real error with retry"], badCaption: "Error and pending states exist in the happy-path mockup but are unhandled in code, so a stuck pending transaction renders as a frozen spinner with no status and no recovery. That is the exact moment that decides whether the user ever trusts the product again.", goodCaption: "Model pending and error as real states with copy and escape hatches: explain why it is stuck and offer speed-up, cancel, and retry. The anxiety moment gets a recovery path instead of a frozen spinner." },
  "buying-psychology-hesitation-inv-8": { archetype: 'toggle-fix', subject: "React app - ConfirmModal", badLabel: "One generic modal, no riskTier prop", goodLabel: "riskTier threaded through the tree", badLines: ["<ConfirmModal message onConfirm /> for 'discard draft'", "<ConfirmModal message onConfirm /> for 'transfer funds'", "No prop distinguishes reversibility", "Irreversible transfer gets the same soft ack as a trivial edit"], goodLines: ["<ConfirmModal riskTier='low' /> discard draft -> soft ack", "<ConfirmModal riskTier='high' /> transfer funds", "riskTier threads through the component tree", "High tier escalates to a typed confirm"], badCaption: "A shared ConfirmModal is used for both 'discard draft' and 'transfer funds' with no prop distinguishing their reversibility. Because risk tier is represented nowhere in the component tree, the irreversible action gets the same weight as the trivial one.", goodCaption: "Thread a riskTier prop through the tree so the signal exists in the architecture. The modal then escalates from a soft ack to a typed confirm by consequence, allocating friction where it belongs." },
  "methods-teardown-strategy-mm-0": { archetype: 'slider-map', sliderLabel: "Habit force: the phone already in your other hand", outputLabel: "Switch outcome", badCaption: "Marketing pushed only Push and Pull. Nobody weighed the Habit of the phone already in hand, so the switch tipped back to stay and returns spiked.", goodCaption: "Model all four forces. When Habit is on the beam, you see the switch tip back and design against the drag instead of just adding more demand." },
  "methods-teardown-strategy-mm-1": { archetype: 'sequence', badSequence: ["Pick metric first: track lessons started", "Starts climb, dashboard looks up", "Completions and next-day return quietly rot", "Vanity number hides the leak"], goodSequence: ["Goal: learner feels they are making progress", "Signal: completes a lesson AND returns the next day", "Metric: streak-driven D1/D7 retention", "Every number traces back to the goal"], badCaption: "Starting from the metric ('lessons started') lets starts climb while completions and retention rot. The vanity number hides the leak.", goodCaption: "Name the goal, then the signal, then the metric. The streak counter is only trustworthy because it is wired to a signal wired to a goal." },
  "methods-teardown-strategy-mm-2": { archetype: 'meter', headline: "Signup to retained: 100% top, but where is the cliff?", breakdown: [{ label: "Signed up", value: 100 }, { label: "Reached the workspace", value: 92 }, { label: "Passed the blank-canvas first run", value: 34 }, { label: "Returned next week", value: 21 }], badCaption: "Read as 'onboarding is bad' and you redesign everything. The rolled-up funnel hides that one step, the blank first-run, is the cliff.", goodCaption: "Name the step: the blank-workspace first run. Templates and a guided first doc aimed at that exact step move the whole retention curve." },
  "methods-teardown-strategy-mm-3": { archetype: 'before-after', subject: "Dropbox research read", badLabel: "Trust what they said (interviews)", goodLabel: "Trust what they did (behavior)", badLines: ["'Give us more features and configuration.'", "Roadmap fills with settings and options.", "You add surface area to a product bleeding at first-sync."], goodLines: ["Session logs: drop-off spikes at install-and-sync.", "Fix aimed at the real leak: a demo video reducing sync anxiety.", "Behavior located the leak; it was never about features."], badCaption: "Building the requested features (what users said) would have added surface area to a product bleeding at first-sync.", goodCaption: "Behavior located the leak at install-and-sync. Drew Houston trusted the do over the say and fixed the actual drop-off." },
  "methods-teardown-strategy-mm-4": { archetype: 'reveal', subject: "Bing A/B result", opaqueLabel: "Significant lift. Ship B.", revealedLines: ["Traffic split: 52 / 48, expected 50 / 50", "Sample Ratio Mismatch detected", "The split is broken, so the lift is a logging artifact", "Rule: SRM fails, throw the whole test out"], badCaption: "The lift looked significant and shippable. Skip the split-ratio check and you ship a logging artifact that never moves the metric in production.", goodCaption: "Check the instrument before you believe the number. The 52/48 split is an SRM, so the whole surprising result is invalidated." },
  "methods-teardown-strategy-mm-5": { archetype: 'meter', headline: "100 findings logged. Which one is load-bearing?", breakdown: [{ label: "Ambiguous transaction status (every send, money, no undo)", value: 97 }, { label: "Confusing fee copy", value: 41 }, { label: "Low-contrast secondary text", value: 18 }, { label: "Inconsistent button radius", value: 6 }], badCaption: "A flat list of 100 nits with no ranking gets ignored, because a founder can't tell what's load-bearing from what's cosmetic.", goodCaption: "Score each on frequency x impact x persistence. Transaction-status ambiguity outranks the entire cosmetic list, so it gets the scarce eng time first." },
  "methods-teardown-strategy-mm-6": { archetype: 'slider-map', sliderLabel: "Number of users in the study", outputLabel: "What this sample size can honestly claim", badCaption: "Reporting '40% can't find it' off 5 sessions is fiction. Discovery finds problems; it can't estimate how many people have them.", goodCaption: "Five users locate the confusing step fast. Quantifying its prevalence is a separate study with a far larger sample." },
  "methods-teardown-strategy-pat-0": { archetype: 'sequence', badSequence: ["Ask: 'Would you like a faster email client?'", "Everyone says yes", "You learn nothing about the real switch"], goodSequence: ["First thought: inbox pain pushes them to look (Push)", "Trial: the slow onboarding almost makes them quit (Anxiety)", "The moment value clicks and they stop reaching for the old client (Pull)", "First value reached: the switch holds"], badCaption: "'Would you like a faster email client?' gets a yes from everyone and tells you nothing about the real decision.", goodCaption: "Walk a recent switcher's timeline backward and tag each moment's dominant force. That is where Superhuman found the anxiety that nearly killed the switch." },
  "methods-teardown-strategy-pat-1": { archetype: 'meter', headline: "Three evaluators, Nielsen's 10, merged and ranked", breakdown: [{ label: "Weak system-status feedback on save (all 3 flagged)", value: 88 }, { label: "Recognition vs recall in the label picker (2 flagged)", value: 55 }, { label: "Minor consistency nit in triage (1 flagged)", value: 22 }], badCaption: "One evaluator catches maybe a third of the violations and calls the rest 'fine.' The single pass hides most of the real set.", goodCaption: "Three independent passes against a shared heuristic list, merged and severity-ranked, surface the real set in an afternoon with no users recruited." },
  "methods-teardown-strategy-pat-2": { archetype: 'sequence', badSequence: ["'Write down your seed phrase' shown as one more field", "Native designer reads it as obvious, moves on", "Beginner's real confusion is never seen"], goodSequence: ["Q1 Will the user try to continue? Yes", "Q2 Do they notice the seed-phrase field? Yes", "Q3 Do they understand why, and what if they lose it? NO", "Q4 Do they get a reassuring progress signal? NO, stop here"], badCaption: "Native crypto designers can't see it: they've lost their beginner eyes, so the seed-phrase wall stays invisible.", goodCaption: "The cognitive walkthrough forces the novice model and stops at the first 'no', exposing the exact step where goal formation breaks." },
  "methods-teardown-strategy-pat-3": { archetype: 'reveal', subject: "Uniswap swap confirmation", opaqueLabel: "Nice confirmation UX. Looks done.", revealedLines: ["toast fires on wallet.sendRequest() resolving", "not on on-chain confirmation", "RPC: tx still pending, could still revert", "You assert completion before the chain knows"], badCaption: "A visual audit says 'nice confirmation UX.' The success signal fired on the send-request resolving, not on confirmation.", goodCaption: "Read the network tab: the toast fired early while the tx is still pending. Asserting completion before the chain knows is the biggest trust leak in crypto." },
  "methods-teardown-strategy-pat-4": { archetype: 'slider-map', sliderLabel: "Raw SUS score", outputLabel: "Sauro-Lewis grade and percentile", badCaption: "The raw delta (71 to 82) undersells the win as a modest bump and buries it in stakeholder review.", goodCaption: "Plot the score on the curve. The redesign moved perceived usability from average to top-tier, which is the number worth reporting." },
  "methods-teardown-strategy-pat-5": { archetype: 'meter', headline: "Aggregate D30 retention: flat and hopeless", breakdown: [{ label: "All users (aggregate)", value: 14 }, { label: "Created a project in week 1", value: 40 }, { label: "Did not create a project in week 1", value: 3 }], badCaption: "The aggregate D30 number looks flat and hopeless and tells the team nothing actionable.", goodCaption: "Split by 'created a project in week 1' and the curve fans apart: creators retain at 40%, non-creators drop to 3%. The whole strategy becomes activating that one behavior." },
  "methods-teardown-strategy-pat-6": { archetype: 'sequence', badSequence: ["'Perplexity sometimes gets citations wrong'", "Reads as a nitpick", "Nobody shares it"], goodSequence: ["Claim: the problem isn't hallucination, it's citations feeling checked", "Annotated evidence: real URL, invented attribution", "Mechanism: post-hoc citation mapping", "Fix: quote the supporting span", "Principle: citations prove checkability, not correctness"], badCaption: "A flat 'Perplexity sometimes gets citations wrong' is a nitpick nobody shares. It reframes nothing.", goodCaption: "Claim, annotated evidence, mechanism, fix, principle. The locked fix slot stops you from shipping a pure dunk, and the reframe earns the share." },
  "methods-teardown-strategy-anti-0": { archetype: 'reveal', subject: "Early-startup A/B call", opaqueLabel: "60% chose B. Clear winner.", revealedLines: ["A: 2/5 = 40%, 95% CI roughly 5% to 85%", "B: 3/5 = 60%, 95% CI roughly 15% to 95%", "The intervals fully overlap", "This is indistinguishable from a coin flip"], badCaption: "'3 of 5 prefer B' looks like a data-backed winner, so eng effort commits to a result that is really just noise.", goodCaption: "Show the intervals on those proportions: they fully overlap. Five users can find problems in both pages but can never rank them." },
  "methods-teardown-strategy-anti-1": { archetype: 'sequence', badSequence: ["Day 2: peek. p = 0.31", "Day 5: peek. p = 0.08", "Day 6: peek. p = 0.04. STOP, declare the win", "Ship the variant"], goodSequence: ["Fix the horizon (or use an always-valid engine) up front", "Do not stop on the first blip under 0.05", "Run to the planned sample", "Effect settles to ~0: it was noise"], badCaption: "Every peek is another chance for noise to cross 0.05. Stopping at the first significant blip ships a false win that reverts in production.", goodCaption: "Commit the horizon before you start, or use sequential testing. Run it out and the phantom effect decays back to zero." },
  "methods-teardown-strategy-anti-2": { archetype: 'reveal', subject: "SaaS board dashboard", opaqueLabel: "NPS +45. Steer by it.", revealedLines: ["Only ~20% of users answered the survey", "Respondents are a self-selected happy minority", "The churned majority never replied", "Meanwhile D30 retention is cratering"], badCaption: "A comforting +45 gets reported to the board while D30 retention quietly craters, and the leak is missed for two quarters.", goodCaption: "NPS is one attitudinal number with no diagnostic power. Retention by cohort shows the leak the self-selected survey structurally can't." },
  "methods-teardown-strategy-anti-3": { archetype: 'meter', headline: "Total signups: rocketing. Looks like a rocket ship.", breakdown: [{ label: "Jan cohort, retained", value: 38 }, { label: "Mar cohort, retained", value: 22 }, { label: "May cohort, retained", value: 11 }, { label: "Jul cohort, retained", value: 4 }], badCaption: "Steering by total signups made Clubhouse look like a rocket while cohort retention quietly collapsed underneath the hype.", goodCaption: "Overlay retention by cohort and each successive wave is worse than the last. The aggregate hid the drain until the acquisition tap turned off." },
  "methods-teardown-strategy-anti-4": { archetype: 'meter', headline: "40 annotated nits. Looks thorough. What do you fix first?", breakdown: [{ label: "Ambiguous transfer status (load-bearing, tagged)", value: 96 }, { label: "Spacing and alignment nits", value: 20 }, { label: "Color and contrast nits", value: 14 }, { label: "Icon inconsistencies", value: 8 }], badCaption: "40 flat spacing and color annotations signal effort, not insight. A founder learns nothing about why users abandon the transfer flow.", goodCaption: "Rank by severity and the wall collapses to a few mechanism-tagged findings. The ambiguous transfer status is the leak worth paying for." },
  "methods-teardown-strategy-anti-5": { archetype: 'before-after', subject: "Checkout usability test", badLabel: "Leading task + moderator rescues", goodLabel: "Goal-only task + silence", badLines: ["'Now use the express checkout button at the top.'", "Moderator jumps in with a hint on every pause.", "Result: 100% success. Readout says the flow is great."], goodLines: ["'Buy this item however you'd normally do it.'", "Moderator stays quiet when the user stalls.", "Real failures surface, matching the production drop-off."], badCaption: "Leading tasks and rescues manufacture a 100% success rate with no relationship to reality, so the team ships a flow the funnel already proves is broken.", goodCaption: "A goal-only task and a quiet moderator let the real leak show. The test's job is to find failure, not to pass." },
  "methods-teardown-strategy-anti-6": { archetype: 'before-after', subject: "JTBD interview script", badLabel: "Solution-first (hypothetical)", goodLabel: "Switch interview (real timeline)", badLines: ["'Would you use an AI summary feature?'", "80 of 100 say yes.", "You build it. Usage is near zero."], goodLines: ["'Tell me about the last time you needed to catch up on a long thread.'", "They reconstruct the actual struggling moment.", "You learn whether real demand exists before you build."], badCaption: "Hypotheticals get agreeable yeses from imagined future selves. 80% yes manufactured false confidence and burned a build cycle on near-zero usage.", goodCaption: "Reconstruct the last real time they reached for it. A Switch interview reveals actual demand instead of a polite prediction." },
  "methods-teardown-strategy-inv-0": { archetype: 'sequence', badSequence: ["User taps Swap", "Wallet broadcasts the transaction", "UI: 'Swap successful!' fires instantly", "Gas spikes; tx gets stuck, then reverts", "User already closed the tab believing it worked"], goodSequence: ["User taps Swap", "Wallet broadcasts the transaction", "UI: 'Submitted, waiting for confirmation...'", "On-chain confirmation received", "Only now: 'Swap complete'"], badCaption: "The success toast fires on broadcast, not confirmation. The user sees success and leaves; the tx reverts and their trust is gone. A one-line ordering bug in the handler.", goodCaption: "Gate the success state on on-chain confirmation. Until the chain confirms, the UI stays honestly pending." },
  "methods-teardown-strategy-inv-1": { archetype: 'toggle-fix', subject: "Image generator", badLabel: "Swallowed error (200 with error field ignored)", goodLabel: "Surface the error the server already knew", badLines: ["Prompt submitted, spinner spins", "Server returns 200 with { error: 'content_policy' }", "Client ignores the error field", "Spinner disappears. No image. No message.", "User re-clicks 3x, burns credits, calls it broken"], goodLines: ["Prompt submitted, spinner spins", "Server returns the content-policy rejection", "Client reads the error field", "Blocked: content policy. Try a different prompt.", "No wasted credits, clear next action"], badCaption: "The server knew the request was rejected, but the 200-with-error was ignored, so the spinner resolved to nothing. The user burned credits chasing a silent failure.", goodCaption: "Read the error field and show it: 'Blocked: content policy.' The failure was known server-side; surfacing it turns a flaky-feeling tool into a clear one." },
  "methods-teardown-strategy-inv-2": { archetype: 'toggle-fix', subject: "Midjourney generation", badLabel: "Bare indeterminate spinner", goodLabel: "Elapsed time + current stage + cancel", badLines: ["Generating...", "(spinner, 45 seconds, no elapsed time)", "No stage. No cancel.", "User assumes it froze, refreshes (double-submits) or leaves"], goodLines: ["Rendering, 0:23 elapsed", "Stage: upscaling variant 3 of 4", "Cancel", "The wait reads as 'working', not 'frozen'"], badCaption: "The 45s wait was normal, but a bare spinner with no status reads as a hang. Users refresh (double-submitting) or abandon the task.", goodCaption: "Show elapsed time, the current stage, and a cancel button. The same wait now reads as visible progress, satisfying visibility of system status." },
  "methods-teardown-strategy-inv-3": { archetype: 'reveal', subject: "dApp token approval", opaqueLabel: "Approve (one tap, looks routine)", revealedLines: ["Decoded: approve(spender, amount)", "amount = unlimited (2^256 - 1)", "spender = 0x9f… (unknown contract)", "This lets the contract drain your entire balance"], badCaption: "'Approve' presented as one routine tap grants an unlimited allowance to an unknown contract. Blind signing is the single most exploited wallet vulnerability.", goodCaption: "Decode the payload into plain language before signing. Now the action's weight matches its blast radius and the user can actually consent." },
  "methods-teardown-strategy-inv-4": { archetype: 'reveal', subject: "Activation funnel", opaqueLabel: "Suspiciously smooth jump between steps", revealedLines: ["Step 1 Signed up: event fires", "Step 2 Reached dashboard: event fires", "Step 3 Connected first data source: NO EVENT WIRED", "The make-or-break step is a hole in the data"], badCaption: "The funnel looks healthy because the make-or-break step was never instrumented. You optimize the visible steps for months while the real leak sits in a blind spot.", goodCaption: "Inspect the instrumentation and the missing event lights up red. You were blind exactly where the leak lives: connect the first data source." },
  "methods-teardown-strategy-inv-5": { archetype: 'toggle-fix', subject: "File upload progress", badLabel: "Fixed-timer bar (CSS animation)", goodLabel: "Bound to real bytes-transferred", badLines: ["Bar animates smoothly on a timer", "Real upload stalls at 30% on a network issue", "Bar ignores it, sails to 95% and hangs", "Then errors. The 'progress' the user watched was a lie"], goodLines: ["Bar reflects actual bytes sent", "Upload stalls at 30%: the bar stalls at 30%", "The stall is visible and honest", "Failure is expected, not a betrayal"], badCaption: "A timer-driven bar sets an expectation of imminent success the real upload can't meet. When it fails after 'showing progress', the betrayal reads as the product lying.", goodCaption: "Bind the bar to bytes-transferred. It stalls honestly when the network does, so the failure never contradicts what the user watched." },
  "methods-teardown-strategy-inv-6": { archetype: 'toggle-fix', subject: "Uniswap swap form", badLabel: "Expert eyes on (jargon reads fine)", goodLabel: "Novice mode (what a first-timer parses)", badLines: ["Slippage tolerance: 0.5%", "Approve spender", "Price impact", "Native builder: all transparent, ships it"], goodLines: ["'Slippage tolerance' maps to nothing they know, greyed out", "'Approve spender' maps to nothing they know, greyed out", "They stall, guess, or leave, unable to form the next action", "Fix: plain-language framing anchored to something they hold"], badCaption: "'Slippage', 'approve spender', 'price impact' are transparent to native builders, so the onboarding leak stays invisible to the people who ship it.", goodCaption: "Turn expert eyes off. Each load-bearing term that maps to nothing a newcomer knows greys out, exposing where goal formation breaks." },
  "methods-teardown-strategy-inv-7": { archetype: 'toggle-fix', subject: "Crypto wallet balance", badLabel: "Cached balance, never invalidated", goodLabel: "Invalidate on mutation, refetch truth", badLines: ["Balance: 1,200 TOKEN (cached from last fetch)", "User sends 500. Send confirms on-chain.", "Client cache is never invalidated", "UI still shows 1,200. User panics: double-spend? theft?"], goodLines: ["Balance: 1,200 TOKEN", "User sends 500. Send confirms on-chain.", "Mutation invalidates the cached balance", "UI refetches and shows 700, matching the chain"], badCaption: "The send succeeded on-chain but the cached balance was never invalidated, so the UI stays stale. The contradiction with chain truth reads as a bug or theft.", goodCaption: "Invalidate the cache on mutation and refetch. The displayed balance tracks the source of truth instead of silently desyncing." },
};

export function demoConfigFor(id: string | undefined): DemoConfig | undefined {
  return id ? DEMO_CONFIGS[id] : undefined;
}
